// Reacts to the viewport crossing the phone/tablet breakpoint — via
// matchMedia's change event, not a one-time window.innerWidth read at
// mount, so rotating a tablet or resizing a browser window updates the
// layout live instead of only being correct on initial page load.
function useIsNarrowScreen(breakpointPx = 768) {
  const [isNarrow, setIsNarrow] = useState(() =>
    typeof window !== "undefined" && window.matchMedia ? window.matchMedia(`(max-width: ${breakpointPx}px)`).matches : false
  );
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia(`(max-width: ${breakpointPx}px)`);
    const onChange = (e) => setIsNarrow(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, [breakpointPx]);
  return isNarrow;
}


// ── Predictive no-show scoring ────────────────────────────────────────────
// Returns { risk: 'HIGH'|'MEDIUM'|null, rate: 0-1, noShows: n, total: n }
// for a given agent across all historical trips. HIGH = 2+ no-shows OR
// ≥40% rate (min 3 trips). MEDIUM = 1 no-show OR 25–40% rate.
// Runs client-side against state.trips — no extra query needed.
function computeNoShowRisk(agentId, allTrips) {
  const agentTrips = allTrips.filter(t =>
    [TRIP_STATE.ARCHIVED_COMPLETED, TRIP_STATE.ARCHIVED_CANCELLED].includes(t.state) &&
    (t.agent_ids || []).some(id => String(id) === String(agentId))
  );
  const total = agentTrips.length;
  if (total === 0) return { risk: null, rate: 0, noShows: 0, total: 0 };
  const noShows = agentTrips.filter(t =>
    (t.no_shows || []).some(ns => String(ns.agent_id) === String(agentId))
  ).length;
  const rate = noShows / total;
  let risk = null;
  if (noShows >= 2 || (total >= 3 && rate >= 0.40)) risk = 'HIGH';
  else if (noShows >= 1 || (total >= 3 && rate >= 0.25)) risk = 'MEDIUM';
  return { risk, rate, noShows, total };
}

// Returns a combined risk for a whole trip (worst of all its agents).
function tripNoShowRisk(trip, allTrips) {
  const agentIds = trip.agent_ids || [];
  let worst = null;
  for (const aid of agentIds) {
    const { risk } = computeNoShowRisk(aid, allTrips);
    if (risk === 'HIGH') return 'HIGH';
    if (risk === 'MEDIUM') worst = 'MEDIUM';
  }
  return worst;
}

function haversineKm(lat1, lng1, lat2, lng2) {
  if (lat1 == null || lng1 == null || lat2 == null || lng2 == null) return Infinity;
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
            Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Collapses pickup coordinates that share the same physical location into
// ONE entry — several agents on the same OUTBOUND trip all pick up at the
// identical company address, and previously each agent's pickup coord was
// kept as its own separate array entry (first + one per extrapickups
// entry). A driver's route-distance/sequencing calculation then treated
// that single physical stop as 2 or 3 SEPARATE stops to "travel between"
// (zero-distance in theory, but this corrupted both the waypoint
// structure sent to the routing API and the ordering it computed —
// confirmed in production: a 3-passenger trip sharing one pickup point
// was showing 110km for a route that's genuinely 76km). Rounds to 5
// decimal places (~1m precision) before comparing, so it still treats two
// coordinates that are merely CLOSE (not byte-identical, e.g. from
// slightly different geocoding passes) as the same stop.
function dedupeCoordsByLocation(coords) {
  const seen = new Map();
  for (const c of coords) {
    if (!c || c.lat == null || c.lng == null) continue;
    const key = `${c.lat.toFixed(5)},${c.lng.toFixed(5)}`;
    if (!seen.has(key)) seen.set(key, c);
  }
  return [...seen.values()];
}

// Sort an array of dropoff coord objects ({ lat, lng, label, agent_id, ... })
// nearest-to-furthest from a given anchor point using nearest-neighbour chaining.
// Used for OUTBOUND trip display so the trip card always shows D1 (closest to
// company) → D2 → D3 (furthest) regardless of agent array order.
// Coords without lat/lng are pushed to the end.
// ── haversine TSP helpers ────────────────────────────────────────────────
// Computes total route distance: anchor → stops[0] → ... → stops[n-1] → (destination?)
function _routeKm(stops, anchor, destination) {
  let km = 0, cur = anchor;
  for (const s of stops) {
    km += haversineKm(cur.lat, cur.lng, s.lat, s.lng);
    cur = s;
  }
  if (destination) km += haversineKm(cur.lat, cur.lng, destination.lat, destination.lng);
  return km;
}

// 2-opt improvement: repeatedly swap pairs of edges until no improvement found.
// Converts a nearest-neighbour solution into a near-optimal one in O(n² * passes).
function _twoOpt(stops, anchor, destination) {
  let route = [...stops];
  let improved = true;
  while (improved) {
    improved = false;
    for (let i = 0; i < route.length - 1; i++) {
      for (let j = i + 1; j < route.length; j++) {
        const before = _routeKm(route, anchor, destination);
        const candidate = [
          ...route.slice(0, i),
          ...route.slice(i, j + 1).reverse(),
          ...route.slice(j + 1),
        ];
        if (_routeKm(candidate, anchor, destination) < before - 0.001) {
          route = candidate;
          improved = true;
        }
      }
    }
  }
  return route;
}

// Brute-force exact TSP for small n — tries all n! permutations.
function _exactTsp(stops, anchor, destination) {
  // Generate all permutations via Heap's algorithm
  const n = stops.length;
  const perm = [...stops];
  const c = new Array(n).fill(0);
  let best = [...perm], bestKm = _routeKm(perm, anchor, destination);
  let i = 0;
  while (i < n) {
    if (c[i] < i) {
      if (i % 2 === 0) [perm[0], perm[i]] = [perm[i], perm[0]];
      else             [perm[c[i]], perm[i]] = [perm[i], perm[c[i]]];
      const km = _routeKm(perm, anchor, destination);
      if (km < bestKm) { bestKm = km; best = [...perm]; }
      c[i]++;
      i = 0;
    } else {
      c[i] = 0;
      i++;
    }
  }
  return best;
}

function sortDropoffCoordsByProximity(coords, anchorCoord, driverEndCoord, destinationCoord = null) {
  // Haversine TSP fallback — minimises TOTAL route km, not just nearest-next-hop.
  // Used when TomTom API is unavailable or returns no result.
  // Strategy: exact brute-force for n ≤ 8 (≤ 40,320 permutations, ~5ms),
  //           2-opt improvement for n > 8 (near-optimal, O(n² × passes)).
  if (!anchorCoord || coords.length <= 1) return coords;
  // isValidCoord (defined below, but a hoisted function declaration so this
  // forward reference is safe) also rejects {0,0} geocoder-fallback
  // sentinels and out-of-CT_BOUNDS coords, not just missing ones — a bad
  // geocode here used to get haversine-distanced against real Cape Town
  // points as if it were a real address, skewing the fallback ordering
  // this function is only ever used for when TomTom is unavailable.
  const valid = coords.filter(c => isValidCoord(c));
  const invalid = coords.filter(c => !isValidCoord(c));
  if (valid.length <= 1) return [...valid, ...invalid];

  // The "destination" for route cost: use destinationCoord (e.g. office for INBOUND)
  // or driverEndCoord (driver's home) if provided. This ensures the optimization
  // accounts for the full trip cost including the final leg.
  const terminus = destinationCoord?.lat != null ? destinationCoord
                 : driverEndCoord?.lat  != null ? driverEndCoord
                 : null;

  let ordered;
  if (valid.length <= 8) {
    // Exact: guaranteed global minimum for this stop count
    ordered = _exactTsp(valid, anchorCoord, terminus);
  } else {
    // Seed with nearest-neighbour, then improve with 2-opt
    const seeded = [];
    let remaining = [...valid], cur = anchorCoord;
    while (remaining.length) {
      let best = null, bestD = Infinity;
      for (const c of remaining) {
        const d = haversineKm(cur.lat, cur.lng, c.lat, c.lng);
        if (d < bestD) { bestD = d; best = c; }
      }
      seeded.push(best);
      cur = best;
      remaining = remaining.filter(c => c !== best);
    }
    ordered = _twoOpt(seeded, anchorCoord, terminus);
  }

  return [...ordered, ...invalid];
}

// Turns a stored "YYYY/MM/DD" scheduled_date into a clear, scannable
// label for a driver's trip card — "TODAY", "TOMORROW", or "Wed, Jul 22"
// for anything further out. Built for exactly this: a driver assigned to
// several days of one agent's week booking (see TRIP/BULK_ASSIGN_DRIVER)
// previously had no way to tell which trip CARD corresponded to which
// DAY, since nothing on the card showed a date at all. Parses the
// slash-format date using explicit year/month/day components (not
// new Date(dateStr) on the raw string) so there's no ambiguity about
// which timezone the string gets interpreted in — the components are
// used directly, local calendar date to local calendar date.
// A person's booking only becomes a "trip" once a driver is actually
// assigned to it — before that (UNASSIGNED_BOOKING) it's still just a
// booking, per explicit product decision. Used everywhere user-facing
// text names a SPECIFIC trip object whose state is known, so the label
// always matches reality instead of calling every booking a "trip"
// regardless of whether a driver has ever touched it.
function tripNoun(trip) {
  return trip?.state === TRIP_STATE.UNASSIGNED_BOOKING ? "booking" : "trip";
}
function tripNounCap(trip) {
  const n = tripNoun(trip);
  return n.charAt(0).toUpperCase() + n.slice(1);
}

// Generic route label for agent-facing views — "Home → Work" / "Work → Home"
// instead of the real street address, per explicit privacy requirement:
// agents should not see any address (their own or anyone else's) on their
// side of the app for either direction. Admin- and driver-facing views are
// unaffected — they still show real addresses, since drivers need them for
// navigation and admins need them for dispatch.
function agentRouteLabel(direction) {
  return direction === "INBOUND" ? "Home → Work" : "Work → Home";
}

function formatTripDateForDriver(dateStr) {
  if (!dateStr) return "—";
  const [y, m, d] = dateStr.split("/").map(Number);
  if (!y || !m || !d) return dateStr;
  const tripDate = new Date(y, m - 1, d);
  const today = new Date();
  const todayMidnight = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const diffDays = Math.round((tripDate - todayMidnight) / 86400000);
  if (diffDays === 0) return "TODAY";
  if (diffDays === 1) return "TOMORROW";
  return tripDate.toLocaleDateString("en-ZA", { weekday: "short", month: "short", day: "numeric" });
}

// Counts DISTINCT CALENDAR DATES across a set of trips, not trip rows.
// A week booking WITH a return leg creates TWO trip rows per day
// (outbound + return, sharing the same scheduled_date and week_day_num
// — see AgentBookTab's week-booking loop) — a return trip is still the
// same day's commute, not a second day. Anywhere the admin sees "N days"
// for a week-booking selection should count this, not selectedTrips.length,
// or a 6-day week with return trips every day would show as "12 days."
function distinctWeekDays(trips) {
  return new Set(trips.map(t => t.scheduled_date)).size;
}

// Builds the FULL optimized route for a driver with one or more active
// trips: starting from wherever the driver currently is, greedily visits
// the nearest remaining pickup each step until all pickups are done, then
// does the same for drop-offs. This is what "quickest route from the
// driver's position, through the pickups, to the drop-offs" means in
// practice — a classic nearest-neighbour heuristic, not a full TSP solve
// (which would be overkill for a handful of stops and isn't guaranteed to
// be meaningfully better for this use case).
//
// Returns { pickupOrder, dropoffOrder, legs, totalRoadKm } where legs is
// the ordered list of individual point-to-point distances (each already
// road-factored via ROAD_FACTOR) that sum to totalRoadKm — this is the
// real "start to finish" route distance, distinct from est_distance_km on
// each trip (which is just that one trip's own pickup-to-dropoff line).
const ROAD_FACTOR = 1.35; // same straight-line-to-road approximation used elsewhere in the app

function computeOptimalRoute(trips, driverCurrentCoord) {
  // Last-resort fallback only — the caller (TRIP/RECORD_ROUTE) always
  // resolves and passes a real coordinate first. No `state` available
  // here (this runs inside the Supabase action handler on an
  // already-extracted coord), so this uses the same hardcoded Cape Town
  // CBD point defaultCompanyAnchor() falls back to, rather than adding a
  // state dependency to an otherwise-pure route-math function.
  const start = driverCurrentCoord || { label: "Cape Town CBD", area: "Cape Town CBD", lat: -33.9249, lng: 18.4241 };
  const legs = [];
  let cur = start;
  let totalKm = 0;
  // The driver's-current-position -> first-pickup leg is used ONLY to
  // determine sequencing (which pickup is genuinely nearest to where the
  // driver actually is right now) — it is deliberately EXCLUDED from the
  // total distance. "Driver's full route" means first pickup through last
  // drop-off, per explicit requirement, not however far the driver had to
  // travel just to reach their first stop (which varies by where they
  // happened to be standing when they tapped Start Trip, and isn't part
  // of the passengers' actual journey).
  let isFirstLeg = true;

  // Every individual pickup point across every trip (a multi-passenger
  // trip contributes one entry per agent, not one per trip) — matches
  // the same [...first, ...extra] pattern used elsewhere in the app for
  // multi-passenger pickup sequencing.
  let remainingPickups = [];
  trips.forEach(t => {
    (t.pickup_sequence_coords || []).forEach(p => {
      remainingPickups.push({ trip_id: t.trip_id, agent_id: p.agent_id, coord: p, kind: "pickup" });
    });
  });

  const pickupOrder = [];
  while (remainingPickups.length) {
    let best = null, bestIdx = -1, bestDist = Infinity;
    remainingPickups.forEach((p, i) => {
      const d = haversineKm(cur.lat, cur.lng, p.coord.lat, p.coord.lng);
      if (d < bestDist) { bestDist = d; best = p; bestIdx = i; }
    });
    const roadKm = bestDist * ROAD_FACTOR;
    legs.push({ from: cur, to: best.coord, km: roadKm, kind: "pickup", trip_id: best.trip_id, agent_id: best.agent_id, excludedFromTotal: isFirstLeg });
    if (!isFirstLeg) totalKm += roadKm;
    isFirstLeg = false;
    cur = best.coord;
    pickupOrder.push(best);
    remainingPickups.splice(bestIdx, 1);
  }

  // Same nearest-neighbour approach for drop-offs, continuing from
  // wherever the last pickup left off — this is what actually answers
  // "then to the drop-offs" as one continuous route rather than treating
  // drop-off ordering as a separate, disconnected problem.
  let remainingDropoffs = [];
  trips.forEach(t => {
    (t.dropoff_sequence_coords || []).forEach(d => {
      remainingDropoffs.push({ trip_id: t.trip_id, coord: d, kind: "dropoff" });
    });
  });

  const dropoffOrder = [];
  while (remainingDropoffs.length) {
    let best = null, bestIdx = -1, bestDist = Infinity;
    remainingDropoffs.forEach((d, i) => {
      const dist = haversineKm(cur.lat, cur.lng, d.coord.lat, d.coord.lng);
      if (dist < bestDist) { bestDist = dist; best = d; bestIdx = i; }
    });
    const roadKm = bestDist * ROAD_FACTOR;
    legs.push({ from: cur, to: best.coord, km: roadKm, kind: "dropoff", trip_id: best.trip_id });
    totalKm += roadKm;
    cur = best.coord;
    dropoffOrder.push(best);
    remainingDropoffs.splice(bestIdx, 1);
  }

  return { pickupOrder, dropoffOrder, legs, totalRoadKm: totalKm };
}

function buildPickupSequence(trips, driverStartCoord) {
  // Last-resort fallback only — every real call site passes a resolved
  // anchor (see defaultCompanyAnchor(state) at the call sites). No
  // `state` available in this pure route-math function.
  const start = driverStartCoord || { label: "Cape Town CBD", area: "Cape Town CBD", lat: -33.9249, lng: 18.4241 };
  let remaining = trips.map(t => ({
    trip: t,
    coord: (t.pickup_sequence_coords && t.pickup_sequence_coords[0]) || start,
  }));
  const ordered = [];
  let cur = start;
  while (remaining.length) {
    let best = null, bestDist = Infinity;
    for (const r of remaining) {
      const d = haversineKm(cur.lat, cur.lng, r.coord.lat, r.coord.lng);
      if (d < bestDist) { bestDist = d; best = r; }
    }
    ordered.push(best);
    cur = best.coord;
    remaining = remaining.filter(r => r !== best);
  }
  return ordered;
}

// TomTom-aware pickup sequencing — same fix applied to dropoffs (see
// tomtomOptimalStopOrder), now covering INBOUND pickup order too. A
// merged multi-agent trip's pickup point is a single entry here (all its
// agents share one pickup location), so this operates over one coord per
// TRIP, same shape buildPickupSequence already expects. Falls back to the
// existing haversine buildPickupSequence if TomTom is unavailable or fails
// — this function is ONLY used at async (Supabase) call sites; the local/
// demo reducer keeps calling the synchronous buildPickupSequence directly,
// since a reducer can't await a network call.
async function buildPickupSequenceTomTom(trips, driverStartCoord, departAtEpoch = null) {
  const start = driverStartCoord || { label: "Cape Town CBD", area: "Cape Town CBD", lat: -33.9249, lng: 18.4241 };
  const haversineResult = buildPickupSequence(trips, driverStartCoord);
  if (trips.length <= 1) return haversineResult;
  const coords = trips.map(t => {
    const c = t.pickup_sequence_coords?.[0] || start;
    return { lat: c.lat, lng: c.lng, trip_id: t.trip_id };
  });
  const tomtomResult = await tomtomOptimalStopOrder(start, coords, departAtEpoch);
  if (!tomtomResult) return haversineResult;
  // Map the TomTom-ordered coords back to their trip objects, preserving
  // the same { trip, coord } shape buildPickupSequence returns.
  const byTripId = new Map(trips.map(t => [t.trip_id, t]));
  const reordered = tomtomResult
    .map(c => {
      const trip = byTripId.get(c.trip_id);
      return trip ? { trip, coord: { lat: c.lat, lng: c.lng } } : null;
    })
    .filter(Boolean);
  return reordered.length === trips.length ? reordered : haversineResult;
}

// Nearest-neighbour route through all drop-offs, continuing the chain
// from wherever the pickup route left off (the LAST pickup stop) — the
// same continuation point live navigation uses (see the DriverNavTab
// dropoff ordering). Previously sorted by scheduled_time first with
// distance-from-a-fixed-branch-point only as a tie-break, which could
// disagree with the driver's actual (distance-minimizing) live route.
// Per explicit decision, dispatch-time sequencing now matches live
// navigation exactly — this is the number a route actually costs in
// petrol, not a scheduling label that happens to usually agree with it.
function buildDropoffSequence(trips, lastPickupCoord) {
  let remaining = [...trips];
  if (!lastPickupCoord || remaining.length <= 1) return remaining;
  const ordered = [];
  let cur = lastPickupCoord;
  while (remaining.length) {
    let best = null, bestDist = Infinity;
    for (const t of remaining) {
      const c = t.dropoff_sequence_coords?.[0];
      const d = c ? haversineKm(cur.lat, cur.lng, c.lat, c.lng) : Infinity;
      if (d < bestDist) { bestDist = d; best = t; }
    }
    ordered.push(best);
    const bestCoord = best.dropoff_sequence_coords?.[0];
    if (bestCoord) cur = { lat: bestCoord.lat, lng: bestCoord.lng };
    remaining = remaining.filter(t => t !== best);
  }
  return ordered;
}

// Picks the correct anchor coord for buildDropoffSequence.
//
// The naive anchor — ordered[ordered.length - 1]?.coord, the last pickup
// in the driver's full cross-trip sequence — is wrong for mixed routes:
// if a driver has both INBOUND (home→work) and OUTBOUND (work→home) trips,
// the last pickup in the overall sequence may be an agent's home address
// (from an inbound leg), which gives a completely wrong starting point for
// sequencing the outbound dropoffs (home addresses that should be ordered
// starting from the company office, not from a random suburb).
//
// Rule: if ANY trip in the driver's set is OUTBOUND, anchor from the
// company coord — outbound dropoffs are home addresses that depart from
// work, and using the company coord for pure-inbound sets (single work
// dropoff) is harmless. Otherwise fall back to the last pickup coord,
// which is correct for pure-inbound routes with multiple home pickups.
// The dropoff chain must always continue from wherever the driver actually
// IS — the last pickup stop — for BOTH directions, per explicit
// requirement: "the shortest route/kms" only comes from a single
// continuous nearest-neighbour chain (driver's start -> pickup 1 -> pickup
// 2 -> ... -> dropoff 1 -> dropoff 2 -> ...), never by resetting to a
// fixed anchor partway through. OUTBOUND previously anchored dropoffs
// from companyCoord instead of the last pickup — meaning a driver who'd
// already picked everyone up near, say, the eastern suburbs would have
// their dropoff route recalculated as if starting fresh from the company
// office, which can send them the LONG way around instead of continuing
// on from where they actually are.
function dropoffAnchor(allForDriver, pickupOrdered, companyCoord) {
  const lastPickup = pickupOrdered[pickupOrdered.length - 1]?.coord;
  return lastPickup ?? companyCoord;
}

// Nearest-neighbour route through all not-yet-done dropoffs, continuing
// the chain from wherever the driver currently is (last completed pickup,
// or the last completed dropoff once some are done) — NOT a single sort
// against one fixed anchor point. A single-anchor sort only gets the
// FIRST stop right: with 3+ dropoffs scattered around a city, "closest
// to where I just was" for every stop independently can route the driver
// right past stop B to reach stop C, then backtrack to B, then on to D —
// exactly the kind of extra petrol this function exists to avoid.
// Already-completed dropoffs are left in their current position (never
// reordered) since the driver has already been there; only the remaining
// ones are chained.
function sortDropoffsByProximity(dropStops, lastPickupCoord) {
  if (!lastPickupCoord || dropStops.length <= 1) return dropStops;
  const done = dropStops.filter(s => s.done);
  let remaining = dropStops.filter(s => !s.done);
  if (remaining.length <= 1) return [...done, ...remaining];
  const ordered = [];
  let cur = lastPickupCoord;
  while (remaining.length) {
    let best = null, bestDist = Infinity;
    for (const s of remaining) {
      const d = haversineKm(cur.lat, cur.lng, s.lat || 0, s.lng || 0);
      if (d < bestDist) { bestDist = d; best = s; }
    }
    ordered.push(best);
    cur = { lat: best.lat, lng: best.lng };
    remaining = remaining.filter(s => s !== best);
  }
  return [...done, ...ordered];
}

// Sums the full route a driver will actually drive across ALL their
// currently-assigned active trips: start anchor -> every pickup in
// sequence -> every dropoff in sequence. Deliberately built from the
// SAME ordered/dropOrdered arrays buildPickupSequence/buildDropoffSequence
// already produce at assignment time, rather than recomputing a separate
// estimate — so this number always matches the route the driver will
// actually navigate, not a second, possibly-diverging guess. Includes
// the road-distance correction factor (ROAD_FACTOR) since straight-line
// haversine distance understates real driving distance.
function computeDriverRouteDistanceKm(startAnchor, orderedPickups, orderedDropoffs) {
  // Same duplicate-stop safety net as tomtomRealRouteKm — skip a leg
  // whose destination is the same physical location the driver is already
  // at (to ~1m precision), rather than adding an artificial zero-purpose
  // out-and-back distance to it.
  let total = 0;
  let cur = startAnchor;
  const isSameSpot = (a, b) => a && b && Math.abs(a.lat - b.lat) < 0.00001 && Math.abs(a.lng - b.lng) < 0.00001;
  // The startAnchor -> first-pickup leg is excluded from the total —
  // "driver's full route" means first pickup through last drop-off, per
  // explicit requirement, not however far the driver has to travel from
  // the company (or wherever) to reach their first stop. startAnchor is
  // still used to determine which pickup is genuinely nearest for
  // sequencing purposes, just not counted toward the distance total.
  let isFirstPickupLeg = true;
  for (const p of orderedPickups) {
    if (!p.coord || isSameSpot(cur, p.coord)) { isFirstPickupLeg = false; continue; }
    if (!isFirstPickupLeg) total += haversineKm(cur.lat, cur.lng, p.coord.lat, p.coord.lng);
    isFirstPickupLeg = false;
    cur = p.coord;
  }
  for (const t of orderedDropoffs) {
    // Iterate ALL per-agent dropoffs on this trip — OUTBOUND multi-agent
    // trips have one home address per agent, not a single shared stop.
    for (const c of (t.dropoff_sequence_coords || [t.dropoff_sequence_coords?.[0]]).filter(Boolean)) {
      if (!c || isSameSpot(cur, c)) continue;
      total += haversineKm(cur.lat, cur.lng, c.lat, c.lng);
      cur = { lat: c.lat, lng: c.lng };
    }
  }
  return total * ROAD_FACTOR;
}

// Company policy: a driver's total route (first pickup to last drop-off)
// should not exceed 40 km for every agent riding in the vehicle at once
// — more passengers means more legitimate detour distance is expected,
// so the cap scales with how many people are actually being driven
// rather than being one fixed number regardless of vehicle load.
// Deliberately a SEPARATE number from the existing 40km single-leg
// threshold (which flags one agent's individual pickup->dropoff
// distance as a long-distance trip) — this caps the driver's WHOLE
// multi-stop route instead.
function companyPolicyDistanceCapKm(totalAgentCount) {
  return 40 * Math.max(1, totalAgentCount);
}

const mkId = () => Math.random().toString(36).slice(2, 9).toUpperCase();
const now = () => new Date().toLocaleString("en-ZA", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
// now() returns a formatted display string, which is what the in-memory
// reducer's mock UI expects everywhere it renders a timestamp directly.
// The real Supabase schema's timestamp columns (ts, timestamp, acceptedat,
// confirmedat, completedat, bookedat, updatedat, etc.) are bigint epoch-ms
// values, not strings — inserting now()'s output into those columns fails
// with Postgres error 22P02. nowEpoch() is for exactly those DB writes.
const nowEpoch = () => Date.now();

/* ---------- MONTHLY ARCHIVE WINDOWS ----------
   Agents and drivers see completed OR cancelled trips in calendar-month
   buckets: the CURRENT month live, plus exactly ONE month of archive (the
   previous calendar month). On the 1st of each month the buckets roll
   over automatically — last month becomes the archive, and the month
   before that EXPIRES from the app's display. Expired trips are NEVER
   deleted: they stay in the backend and remain reachable through the
   admin Trip History range queries and the Help tab's full-history
   trip picker. scheduled_date is "YYYY/MM/DD" (en-ZA), so a 7-char
   prefix compare is an exact calendar-month match. Only genuinely-ACTIVE
   trips (booked/assigned/in-transit) never expire regardless of date —
   an old stuck booking should stay visible, not vanish. A cancelled trip
   is just as "done" as a completed one and should age out the same way
   (see tripArchiveBucket — this was a real bug once: it only checked
   ARCHIVED_COMPLETED, so a cancelled trip from any point in an agent's
   history stayed pinned under "CURRENT" forever, the exact same bug
   shape fixed in the week-booking reveal gate this session). */
const monthPrefixOf = (d) => `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}`;
const currentMonthPrefix = () => monthPrefixOf(new Date());
const previousMonthPrefix = () => {
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  return monthPrefixOf(d);
};
const archiveMonthLabel = () => {
  const d = new Date();
  d.setDate(1);
  d.setMonth(d.getMonth() - 1);
  return d.toLocaleString("en-ZA", { month: "long", year: "numeric" }).toUpperCase();
};
function tripArchiveBucket(trip) {
  if (![TRIP_STATE.ARCHIVED_COMPLETED, TRIP_STATE.ARCHIVED_CANCELLED].includes(trip.state)) return "CURRENT";
  const mp = String(trip.scheduled_date || "").slice(0, 7);
  if (mp === currentMonthPrefix()) return "CURRENT";
  if (mp === previousMonthPrefix()) return "ARCHIVE";
  return "EXPIRED";
}
// Converts an epoch-ms value (as read back from Supabase) into the same
// display format now() produces, so the UI shows "11/07/2026, 19:34"
// instead of a raw number like 1752262440000.
const epochToDisplay = (ms) => (ms == null ? null : new Date(ms).toLocaleString("en-ZA", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" }));

// Parses the app's booking-form date/time strings into a real Date object.
// scheduled_date is typically "DD/MM/YYYY" (en-ZA locale, what the booking
// form's date default produces) but the field is free-text — admins/agents
// can type other formats, so this tries DD/MM/YYYY first (the expected case)
// and falls back to whatever the JS Date constructor can natively parse
// (handles ISO "YYYY-MM-DD" and a few other common shapes). Returns null
// rather than throwing if nothing works, so callers can skip time-sensitive
// checks gracefully instead of crashing on a malformed date string.
function parseScheduledDateTime(dateStr, timeStr) {
  if (!dateStr || !timeStr) return null;
  const [h, m] = String(timeStr).split(":").map(Number);
  if (Number.isNaN(h) || Number.isNaN(m)) return null;

  const ddmmyyyy = String(dateStr).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (ddmmyyyy) {
    const [, dd, mm, yyyy] = ddmmyyyy;
    const d = new Date(Number(yyyy), Number(mm) - 1, Number(dd), h, m, 0, 0);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  // YYYY/MM/DD — what the booking form's free-text Date field actually
  // defaults to (confirmed from the running app), distinct from the
  // DD/MM/YYYY case above. Checked explicitly since 2026/07/11 is
  // ambiguous against the DD/MM/YYYY regex and was silently failing,
  // leaving scheduledtime null against a NOT NULL column.
  const yyyymmddSlash = String(dateStr).match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);
  if (yyyymmddSlash) {
    const [, yyyy, mm, dd] = yyyymmddSlash;
    const d = new Date(Number(yyyy), Number(mm) - 1, Number(dd), h, m, 0, 0);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  // YYYY-MM-DD (ISO, e.g. from a native <input type="date">)
  const yyyymmddDash = String(dateStr).match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (yyyymmddDash) {
    const [, yyyy, mm, dd] = yyyymmddDash;
    const d = new Date(Number(yyyy), Number(mm) - 1, Number(dd), h, m, 0, 0);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  const fallback = new Date(`${dateStr}T${String(timeStr).padStart(5, "0")}:00`);
  return Number.isNaN(fallback.getTime()) ? null : fallback;
}

function getDriverLoad(state, driver_id, scheduledDate) {
  // Counts PASSENGERS (summed across the driver's active trips ON THE
  // GIVEN DATE), not trips, and not across all dates. A driver's trips
  // on the SAME day all run on one vehicle at once — DriverNavTab
  // flattens a day's active trips into a single combined route — so the
  // real capacity constraint is "how many people are aboard this one
  // day," and DRIVER_CAPACITY is a seat count (the UI says "X/4 seats"
  // everywhere). Trips on DIFFERENT days never share a vehicle at the
  // same time, so they must never compete for the same 4 seats — a
  // driver already assigned to 4 different days of one agent's week
  // booking is NOT "full" for a 5th, unrelated day. scheduledDate is
  // required (not optional) so a caller can't accidentally omit it and
  // silently fall back to the old, wrong all-dates behavior; pass the
  // trip's own scheduled_date when checking whether it can be assigned.
  return state.trips
    .filter(t => String(t.driver_id) === String(driver_id) && ![TRIP_STATE.ARCHIVED_COMPLETED, TRIP_STATE.ARCHIVED_CANCELLED].includes(t.state) && t.scheduled_date === scheduledDate)
    .reduce((seats, t) => seats + Math.max(1, t.agent_ids?.length || 0), 0);
}

// Counts DISTINCT TRIP RECORDS for a driver on a given date — a
// genuinely different question from getDriverLoad's seat-capacity count
// above. Deliberately INCLUDES completed trips (getDriverLoad excludes
// them, since a finished trip no longer occupies a seat) — the point
// here is "how much has this driver already driven today," a workload
// signal, so a driver who's already wrapped up 6 runs today is exactly
// the case worth surfacing, not something to quietly drop from the count
// the moment each trip finishes.
function getDriverTripCountForDate(state, driver_id, scheduledDate) {
  return state.trips.filter(t => String(t.driver_id) === String(driver_id) && t.scheduled_date === scheduledDate).length;
}

/* ---------- WAZE NAVIGATION (web: window.open instead of RN Linking) ----------
   Per Waze's own developer docs (developers.google.com/waze/deeplinks), the
   single https://waze.com/ul URL is the correct link for every platform —
   it already branches internally based on the user's device:
     - Desktop: opens the Waze web page (there is no Waze desktop app)
     - Mobile with the Waze app installed: opens the app directly
     - Mobile without the app: opens the Waze web page
   The alternative waze:// scheme is documented as unreliable outside cases
   where the app is guaranteed to be installed — "if users tap the link,
   nothing happens" otherwise. Using only the https:// link avoids the
   silent-failure risk that approach carries on desktop. */
function buildWazeLink(lat, lng, label = "") {
  const params = new URLSearchParams({ ll: `${lat},${lng}`, navigate: "yes" });
  if (label) params.set("q", label);
  return `https://www.waze.com/ul?${params}`;
}
function openWaze(lat, lng, label = "") {
  window.open(buildWazeLink(lat, lng, label), "_blank", "noopener,noreferrer");
}

// Text-only fallback for when a manually-typed address couldn't be
// geocoded (TomTom unavailable or the address wasn't found) — no lat/lng
// at all, just the address string. Waze's own app/website resolves the
// search itself once it opens, exactly like typing the address directly
// into Waze. Manual addresses that DO geocode successfully use the
// regular coordinate-based buildWazeLink instead (see AgentBookTab's
// submit — pickupIsManual/dropoffIsManual only stay true on failure).
function buildWazeAddressLink(address) {
  const params = new URLSearchParams({ q: address, navigate: "yes" });
  return `https://www.waze.com/ul?${params}`;
}
function openWazeByAddress(address) {
  window.open(buildWazeAddressLink(address), "_blank", "noopener,noreferrer");
}

// Single entry point for every Waze button in the app — checks isManual
// first and routes to the text-only search link when true, since a
// manually-typed address's lat/lng is a meaningless placeholder (see
// AgentBookTab's submit for why) and must never be sent to Waze as if it
// were a real coordinate.
function smartOpenWaze(lat, lng, label, isManual) {
  if (isManual && label) { openWazeByAddress(label); return; }
  if (lat != null && lng != null) openWaze(lat, lng, label);
}

// Single source of truth for whether in-app chat/calling should be
// available for a given trip — only once the driver has confirmed
// (accepted the assignment) or the trip is already in transit. Before
// that (still just ASSIGNED, not yet confirmed) or after completion,
// messaging/calling is disabled — used consistently everywhere a chat
// or call button appears, so there's one place to change this rule
// rather than a scattered per-button check that's easy to miss updating.
function isTripActiveForComms(trip) {
  return trip && [TRIP_STATE.DRIVER_CONFIRMED, TRIP_STATE.IN_TRANSIT].includes(trip.state);
}

// Single source of truth for "does this notification pertain to this
// specific person" — matches the two real targeting models already used
// throughout the app: agent/driver notifications are addressed to a
// specific user via for_user_ids; admin notifications are broadcast to
// the whole admin queue via for_roles (not to one specific admin, since
// admins share a queue). Used for both the toast popup and the alert
// sound, so a person only ever hears/sees a notification meant for them
// — not literally every notification in the system, which is what the
// toast was doing before this existed.
function isNotificationForUser(n, user) {
  if (!user) return false;
  if (n.for_user_ids?.length) return n.for_user_ids.some(id => String(id) === String(user.id));
  if (user.role === ROLE.ADMIN) return !n.for_roles?.length || n.for_roles.includes(ROLE.ADMIN);
  return false;
}

/* ---------- ADDRESS SEARCH (offline DB + OpenStreetMap Nominatim) ---------- */
// Nominatim is OpenStreetMap's free, public geocoding search — no API key,
// no billing account, no script tag, and it sends proper CORS headers so a
// plain fetch() from the browser works out of the box. This replaced Google
// Places because that requires a correctly billed + API-enabled Cloud
// Console project, which isn't something that can be diagnosed or fixed
// from here — Nominatim needs zero setup and just works.
const CPT_BOUNDS = { north: -33.55, south: -34.25, east: 19.05, west: 18.25 };
const GENERIC_ROAD_WORDS = new Set([
  "street", "road", "avenue", "drive", "way", "lane", "close", "crescent",
  "boulevard", "square", "place", "walk", "terrace", "rise", "view", "park",
  "circle", "loop", "court", "heights", "hill", "bay", "cape", "town",
]);

function staticSearch(query) {
  if (!query || query.trim().length < 2) return [];
  const q = query.toLowerCase().trim();
  const qNoNum = q.replace(/^\d+\s*/, "");
  const words = qNoNum.split(/\s+/).filter(w => w.length >= 2 && !GENERIC_ROAD_WORDS.has(w) && !/^\d+$/.test(w));
  if (words.length === 0) return [];
  return CPT_ADDRESS_DB
    .map(addr => {
      const lbl = addr.label.toLowerCase();
      const street = lbl.split(",")[0];
      let score = 0;
      let streetMatched = false;
      if (street.includes(qNoNum) && qNoNum.length >= 3) { score += 100; streetMatched = true; }
      words.forEach(w => {
        if (street.startsWith(w)) { score += 25; streetMatched = true; }
        if (street.includes(w)) { score += 15; streetMatched = true; }
        if (addr.area.toLowerCase().includes(w)) score += 5;
      });
      return (streetMatched && score > 0) ? { ...addr, score, source: "local" } : null;
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .slice(0, 6);
}

// Nominatim's usage policy asks for a descriptive User-Agent/Referer, but
// browsers set Referer automatically and block scripts from overriding it —
// there's nothing extra to configure here. Requests are capped to Cape
// Town's bounding box via viewbox+bounded so results don't drift to other
// cities that happen to share a street name.
/* ---------- TOMTOM SEARCH & GEOCODING (optional — falls back to Nominatim if absent) ----------
   Replaces the earlier Google Places/Geocoding integration entirely — one
   vendor now covers address search (this block), driving routes/ETA, and
   GPS map-matching (see the driver-tracking code further down), instead
   of juggling separate Google + TomTom billing.

   Called via plain fetch() against TomTom's REST endpoints (Search API
   for autocomplete, Geocoding API for complete addresses) — both accept
   the API key as a query parameter and are CORS-friendly for GET
   requests, the same pattern already used for Nominatim in this file.
   No SDK script tag or session-token dance needed, which is simpler than
   the Google integration this replaces.

   Requires VITE_TOMTOM_API_KEY in your .env file (see .env.example). If
   it's missing, TomTom is silently skipped and the app runs on Nominatim
   alone, exactly as it did before either paid integration existed. */
const TOMTOM_API_KEY = import.meta.env?.VITE_TOMTOM_API_KEY || null;
console.log(
  TOMTOM_API_KEY
    ? "[TomTom] API key loaded."
    : "[TomTom] No VITE_TOMTOM_API_KEY found in env — falling back to Nominatim. Check your .env file and restart 'npm run dev'."
);

// ── FEATURE: Route cache (time-of-day window, 30-min TTL) ─────────────────
// Avoids repeat TomTom API calls for the same driver/stop set on the same
// scheduled run. Key: sorted waypoint fingerprint + departAt hour window.
// Uber/Bolt use a much more sophisticated version — this is the same idea
// scoped to TransitOS's fixed-schedule runs where routes genuinely repeat.









// ── Insurance & compliance triggers ──────────────────────────────────────
const COMPLIANCE_ROUTE_MAX_KM = 80;  // notify when driver route > 80 km
// A shift-duration compliance check (originally planned: notify when a
// driver's been online > 10h) was never actually implemented below — there's
// no shift-start timestamp anywhere in driver_status to check against
// (only a plain isonline boolean), so it would need a real schema change,
// not just wiring up existing pieces. Left out of scope for now.

// Called inside TRIP/ASSIGN_DRIVER and TRIP/ADD_AGENT after route is computed.
// Returns array of compliance issues (empty = all clear).
function checkComplianceTriggers(driverUser, driverStatus, routeDistanceKm, totalPassengers) {
  const issues = [];
  if (routeDistanceKm > COMPLIANCE_ROUTE_MAX_KM) {
    issues.push({
      type: "COMPLIANCE_DISTANCE",
      message: `⚠ COMPLIANCE: ${driverUser?.name || "Driver"}'s route is ${routeDistanceKm.toFixed(1)} km — exceeds the ${COMPLIANCE_ROUTE_MAX_KM} km insurance notification threshold.`,
    });
  }
  // Vehicle licence category check: minibus (≤15 pax) vs midi-bus (>15)
  const cap = driverStatus?.capacity || DRIVER_CAPACITY;
  if (totalPassengers > cap) {
    issues.push({
      type: "COMPLIANCE_OVERLOAD",
      message: `⚠ COMPLIANCE: ${driverUser?.name || "Driver"}'s vehicle capacity is ${cap} but ${totalPassengers} passengers are assigned — vehicle overloaded.`,
    });
  }
  return issues;
}

// ── Digital waybill ───────────────────────────────────────────────────────
// Opens a print-ready HTML page for a driver's full day — all trips,
// all passengers, pickup and dropoff addresses in sequence.
// window.print() triggers the system print/PDF dialog.
function generateWaybillHtml(driverUser, driverStatus, trips, users, dateStr) {
  const driverTrips = trips
    .filter(t => String(t.driver_id) === String(driverUser.id) && t.scheduled_date === dateStr)
    .sort((a, b) => (a.pickup_order_num || 99) - (b.pickup_order_num || 99));

  const agentName = (id) => users.find(u => String(u.id) === String(id))?.name || id;
  const agentStaff = (id) => users.find(u => String(u.id) === String(id))?.staff_number || "";

  const tripRows = driverTrips.flatMap(t => {
    const agentIds = t.agent_ids || [];
    return agentIds.map((aid, idx) => {
      // "find by agent_id, else by position, else index 0" — matches the
      // convention already established/fixed everywhere else this
      // session. This function still had the OLD, narrower "find by
      // agent_id, else index 0" pattern (missing the middle positional
      // fallback), which for any untagged coord (still possible for
      // legacy data) meant every non-first passenger on a multi-passenger
      // trip got the FIRST passenger's pickup/dropoff address printed on
      // their own waybill row.
      const pickup = t.pickup_sequence_coords?.find(p => String(p.agent_id) === String(aid)) || t.pickup_sequence_coords?.[idx] || t.pickup_sequence_coords?.[0];
      const dropoff = t.dropoff_sequence_coords?.find(d => String(d.agent_id) === String(aid)) || t.dropoff_sequence_coords?.[idx] || t.dropoff_sequence_coords?.[0];
      return {
        tripId: t.trip_id,
        agent: agentName(aid),
        staff: agentStaff(aid),
        pickup: pickup?.label || t.custom_pickup || "—",
        dropoff: dropoff?.label || t.custom_dropoff || "—",
        pickupSeq: t.pickup_order_num || "—",
        dropSeq: t.drop_sequence_num || "—",
        time: t.scheduled_time || "—",
        type: t.trip_type || "",
        direction: t.direction || "",
      };
    });
  });

  // Agent name, pickup/dropoff labels, vehicle, phone all ultimately come
  // from user-editable text (profile fields, manual "Type Address"
  // entry) — this is written via document.write() into a real browser
  // window (see printWaybill), so unescaped HTML here is a genuine XSS
  // vector, same class as the daily-trip-sheet email bug already fixed
  // this session. That fix's esc() helper had no counterpart here at all.
  const esc = (v) => String(v ?? "").replace(/[&<>"']/g, c => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]
  ));

  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Waybill — ${esc(driverUser.name)} — ${esc(dateStr)}</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #000; padding: 20px; }
  h1 { font-size: 18px; margin: 0 0 4px; }
  .meta { font-size: 11px; color: #555; margin-bottom: 16px; }
  table { width: 100%; border-collapse: collapse; }
  th { background: #1a1a2e; color: #fff; padding: 6px 8px; text-align: left; font-size: 10px; letter-spacing: 0.5px; }
  td { padding: 6px 8px; border-bottom: 1px solid #ddd; font-size: 11px; vertical-align: top; }
  tr:nth-child(even) td { background: #f9f9f9; }
  .badge { display: inline-block; padding: 1px 6px; border-radius: 2px; font-size: 9px; font-weight: 700; }
  .inbound { background: #e3f2fd; color: #1565c0; }
  .outbound { background: #fce4ec; color: #b71c1c; }
  @media print { body { padding: 0; } }
</style></head><body>
<h1>Pearce &amp; Sons — Driver Waybill</h1>
<div class="meta">
  <strong>${esc(driverUser.name)}</strong> | ${esc(driverStatus?.vehicle || "—")} | ${esc(driverStatus?.phone || "—")}<br>
  Date: <strong>${esc(dateStr)}</strong> | Trips: <strong>${driverTrips.length}</strong> | Passengers: <strong>${tripRows.length}</strong>
</div>
<table>
  <thead><tr>
    <th>#</th><th>Time</th><th>Agent</th><th>Staff</th><th>Type</th><th>Pickup Address</th><th>Dropoff Address</th><th>P</th><th>D</th>
  </tr></thead>
  <tbody>
  ${tripRows.map((r, i) => "<tr>" +
    "<td>" + (i + 1) + "</td>" +
    "<td>" + esc(r.time) + "</td>" +
    "<td>" + esc(r.agent) + "</td>" +
    "<td>" + esc(r.staff) + "</td>" +
    "<td><span class=\"badge " + esc(r.direction?.toLowerCase() || '') + "\">" + esc(r.type) + " " + esc(r.direction) + "</span></td>" +
    "<td>" + esc(r.pickup) + "</td>" +
    "<td>" + esc(r.dropoff) + "</td>" +
    "<td>" + esc(r.pickupSeq) + "</td>" +
    "<td>" + esc(r.dropSeq) + "</td>" +
  "</tr>").join('')}
  </tbody>
</table>
<div style="margin-top: 20px; font-size: 10px; color: #888;">
  Generated by TransitOS — Pearce &amp; Sons Fleet Operations — ${new Date().toLocaleString("en-ZA")}
</div>
</body></html>`;
}

function printWaybill(driverUser, driverStatus, trips, users, dateStr) {
  const html = generateWaybillHtml(driverUser, driverStatus, trips, users, dateStr);
  const w = window.open("", "_blank");
  if (!w) { alert("Pop-up blocked — please allow pop-ups for this site to print waybills."); return; }
  w.document.write(html);
  w.document.close();
  w.focus();
  setTimeout(() => w.print(), 400);
}



// ── Booking rate limiter ──────────────────────────────────────────────────
// Prevents accidental duplicate-submission floods and malicious abuse.
// Client-side: tracks timestamps in sessionStorage (clears on tab close).
// Max 3 bookings per 5 minutes per user.
const RATE_LIMIT_MAX = 3;
const RATE_LIMIT_WINDOW_MS = 5 * 60 * 1000; // 5 min
const RATE_LIMIT_KEY = "transitos_booking_rate";

function checkBookingRateLimit(userId) {
  try {
    const raw = sessionStorage.getItem(RATE_LIMIT_KEY);
    const record = raw ? JSON.parse(raw) : {};
    const userRecord = record[userId] || [];
    const now = Date.now();
    // Prune timestamps outside the window
    const recent = userRecord.filter(ts => now - ts < RATE_LIMIT_WINDOW_MS);
    if (recent.length >= RATE_LIMIT_MAX) {
      const oldest = Math.min(...recent);
      const resetIn = Math.ceil((RATE_LIMIT_WINDOW_MS - (now - oldest)) / 1000);
      return { allowed: false, resetIn };
    }
    // Record this booking attempt
    recent.push(now);
    record[userId] = recent;
    sessionStorage.setItem(RATE_LIMIT_KEY, JSON.stringify(record));
    return { allowed: true };
  } catch {
    return { allowed: true }; // fail open — don't block on storage error
  }
}




// ── Trip dispute resolution ───────────────────────────────────────────────
const DISPUTE_CATEGORIES = [
  "Driver did not arrive",
  "Driver was very late (30+ min)",
  "Wrong pickup location",
  "Driver behaviour issue",
  "Trip marked complete but wasn't",
  "Charged incorrectly",
  "Other",
];

const DISPUTE_STATE = { OPEN: "OPEN", DRIVER_RESPONDED: "DRIVER_RESPONDED", RESOLVED_UPHELD: "RESOLVED_UPHELD", RESOLVED_DISMISSED: "RESOLVED_DISMISSED" };

function DisputeFilingModal({ trip, user, dispatch, onClose }) {
  const [category, setCategory] = React.useState("");
  const [description, setDescription] = React.useState("");
  const [submitting, setSubmitting] = React.useState(false);
  const [err, setErr] = React.useState(null);

  const submit = async () => {
    if (!category) { setErr("Please select a category."); return; }
    if (description.trim().length < 10) { setErr("Please describe the issue (at least 10 characters)."); return; }
    setSubmitting(true);
    try {
      await dispatch({
        type: "TRIP/FILE_DISPUTE",
        trip_id: trip.trip_id,
        agent_id: user.id,
        category,
        description: description.trim(),
        filed_at: Date.now(),
      });
      onClose();
    } catch (e) {
      setErr(e.message || "Failed to file dispute.");
      setSubmitting(false);
    }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", zIndex: 1000, display: "flex", alignItems: "flex-end", justifyContent: "center" }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div style={{ width: "100%", maxWidth: 480, background: COLORS.panel, borderTopLeftRadius: 12, borderTopRightRadius: 12, border: `1px solid ${COLORS.wire}`, borderBottom: "none", padding: 20, display: "flex", flexDirection: "column", gap: 12, maxHeight: "85vh", overflowY: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: COLORS.red, letterSpacing: 1 }}>⚠ FILE A DISPUTE</span>
          <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.ghost, fontSize: 16, cursor: "pointer" }}>✕</button>
        </div>
        <div style={{ fontSize: 10, color: COLORS.ghost }}>Trip #{trip.trip_id} · {trip.scheduled_date}. Your dispute will be reviewed by dispatch within 24 hours.</div>
        <div style={{ fontSize: 10, fontWeight: 700, color: COLORS.chalk, letterSpacing: 0.5 }}>CATEGORY *</div>
        {DISPUTE_CATEGORIES.map(c => (
          <div key={c} onClick={() => setCategory(c)}
            style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 10px", borderRadius: 4, border: `1px solid ${category === c ? COLORS.red : COLORS.wire}`, background: category === c ? "rgba(220,53,69,0.08)" : COLORS.surface, cursor: "pointer" }}>
            <div style={{ width: 12, height: 12, borderRadius: "50%", border: `2px solid ${category === c ? COLORS.red : COLORS.ghost}`, background: category === c ? COLORS.red : "transparent", flexShrink: 0 }} />
            <span style={{ fontSize: 11, color: COLORS.chalk }}>{c}</span>
          </div>
        ))}
        <div style={{ fontSize: 10, fontWeight: 700, color: COLORS.chalk, letterSpacing: 0.5 }}>DESCRIPTION *</div>
        <textarea value={description} onChange={e => setDescription(e.target.value)}
          placeholder="Describe what happened in detail…" rows={4} maxLength={800}
          style={{ fontFamily: "inherit", fontSize: 11, background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: 8, color: COLORS.chalk, resize: "vertical", boxSizing: "border-box", width: "100%" }} />
        {err && <div style={{ fontSize: 10, color: COLORS.red }}>{err}</div>}
        <div style={{ display: "flex", gap: 8 }}>
          <Button title="CANCEL" variant="ghost" style={{ flex: 1 }} onClick={onClose} disabled={submitting} />
          <Button title={submitting ? "SUBMITTING…" : "⚠ SUBMIT DISPUTE"} variant="danger" style={{ flex: 1 }} onClick={submit} disabled={submitting} />
        </div>
      </div>
    </div>
  );
}

function DisputeAdminPanel({ trip, dispatch, users }) {
  const dispute = trip.dispute;
  const [resolution, setResolution] = React.useState("");
  const [resolving, setResolving] = React.useState(false);
  if (!dispute) return null;
  const filer = users.find(u => u.id?.toString() === dispute.agent_id?.toString());

  const resolve = async (outcome) => {
    if (!resolution.trim()) return;
    setResolving(true);
    await dispatch({ type: "TRIP/RESOLVE_DISPUTE", trip_id: trip.trip_id, outcome, resolution_note: resolution.trim() }).catch(() => {});
    setResolving(false);
  };

  const stateColor = { OPEN: COLORS.red, DRIVER_RESPONDED: COLORS.amber, RESOLVED_UPHELD: COLORS.green, RESOLVED_DISMISSED: COLORS.ghost }[dispute.state] || COLORS.ghost;

  return (
    <div style={{ background: "rgba(220,53,69,0.05)", border: "1px solid rgba(220,53,69,0.25)", borderRadius: 6, padding: 12, display: "flex", flexDirection: "column", gap: 8 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: COLORS.red }}>⚠ DISPUTE</span>
        <span style={{ fontSize: 10, fontWeight: 700, color: stateColor }}>{dispute.state?.replace(/_/g, " ")}</span>
      </div>
      <div style={{ fontSize: 10, color: COLORS.chalk, fontWeight: 700 }}>{dispute.category}</div>
      <div style={{ fontSize: 10, color: COLORS.ghost }}>{dispute.description}</div>
      <div style={{ fontSize: 9, color: COLORS.ghost }}>Filed by {filer?.name || dispute.agent_id} · {new Date(dispute.filed_at).toLocaleString("en-ZA")}</div>
      {dispute.state === DISPUTE_STATE.OPEN && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 4 }}>
          <textarea value={resolution} onChange={e => setResolution(e.target.value)}
            placeholder="Resolution note (required before closing)…" rows={2}
            style={{ fontFamily: "inherit", fontSize: 11, background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: 8, color: COLORS.chalk, resize: "vertical", boxSizing: "border-box", width: "100%" }} />
          <div style={{ display: "flex", gap: 6 }}>
            <Button title="✓ UPHOLD" variant="green" size="sm" style={{ flex: 1 }} onClick={() => resolve("RESOLVED_UPHELD")} disabled={resolving || !resolution.trim()} />
            <Button title="✗ DISMISS" variant="ghost" size="sm" style={{ flex: 1 }} onClick={() => resolve("RESOLVED_DISMISSED")} disabled={resolving || !resolution.trim()} />
          </div>
        </div>
      )}
      {dispute.resolution_note && (
        <div style={{ fontSize: 9, color: COLORS.ghost, borderTop: `1px solid ${COLORS.wire}`, paddingTop: 6 }}>
          Resolution: {dispute.resolution_note}
        </div>
      )}
    </div>
  );
}


// ── Session timeout ───────────────────────────────────────────────────────
// 30-minute inactivity auto-logout for admin and agent roles.
// Resets on any mouse move, key press, or touch event.
// Shows a warning modal at 5 minutes remaining.
const SESSION_TIMEOUT_MS = 30 * 60 * 1000;   // 30 min total
const SESSION_WARN_MS    =  5 * 60 * 1000;   // warn at 5 min remaining

function useSessionTimeout(user, onLogout) {
  const [warningVisible, setWarningVisible] = React.useState(false);
  const [secondsLeft, setSecondsLeft] = React.useState(null);
  const timerRef = React.useRef(null);
  const warnTimerRef = React.useRef(null);
  const countdownRef = React.useRef(null);
  // Store onLogout in a ref so resetTimer never needs it as a dependency —
  // avoids the chain where onLogout changes → resetTimer recreated → useEffect
  // fires → timers restart → appears as phantom logout activity.
  const onLogoutRef = React.useRef(onLogout);
  React.useEffect(() => { onLogoutRef.current = onLogout; }, [onLogout]);
  // Track whether the page is hidden (backgrounded) — don't count background
  // time toward the inactivity timer. Pause on hide, resume on show.
  const hiddenAtRef = React.useRef(null);
  const remainingAtHideRef = React.useRef(null);
  // Synced copy of warningVisible for the activity listener below to read
  // without needing it in that effect's dependency array (which would
  // tear down/re-add the listeners on every warning toggle).
  const warningVisibleRef = React.useRef(false);

  const resetTimer = React.useCallback(() => {
    warningVisibleRef.current = false;
    setWarningVisible(false);
    setSecondsLeft(null);
    clearTimeout(timerRef.current);
    clearTimeout(warnTimerRef.current);
    clearInterval(countdownRef.current);
    hiddenAtRef.current = null;
    remainingAtHideRef.current = null;

    warnTimerRef.current = setTimeout(() => {
      warningVisibleRef.current = true;
      setWarningVisible(true);
      setSecondsLeft(SESSION_WARN_MS / 1000);
      countdownRef.current = setInterval(() => {
        setSecondsLeft(s => {
          if (s <= 1) { clearInterval(countdownRef.current); return 0; }
          return s - 1;
        });
      }, 1000);
    }, SESSION_TIMEOUT_MS - SESSION_WARN_MS);

    timerRef.current = setTimeout(() => {
      onLogoutRef.current();
    }, SESSION_TIMEOUT_MS);
  }, []); // stable — no deps that change

  React.useEffect(() => {
    if (!user || user.role === ROLE.DRIVER) return;

    // Activity events — use pointer events (covers both mouse and touch),
    // plus keydown and scroll. 'pointerdown' fires reliably on iOS Safari
    // where 'touchstart' can be suppressed by passive listeners on some
    // elements; 'touchend' is included as belt-and-suspenders for older iOS.
    const events = ["pointermove", "pointerdown", "keydown", "touchend", "scroll", "visibilitychange"];
    const handleActivity = (e) => {
      if (e.type === "visibilitychange") {
        if (document.hidden) {
          // Page backgrounded — record how much time was left on each timer
          hiddenAtRef.current = Date.now();
          // We can't read the exact remaining time from setTimeout, so we
          // clear and restart on visibility restore to keep things simple.
        } else {
          // Page foregrounded — only reset if hidden for > 60 s to avoid
          // penalising very brief tab switches (e.g. checking Waze then
          // coming back).
          const hiddenMs = hiddenAtRef.current ? Date.now() - hiddenAtRef.current : 0;
          hiddenAtRef.current = null;
          if (hiddenMs < 60000) {
            // Brief background: restart timer as though they just acted
            resetTimer();
          }
          // Long background: don't reset — let the existing timer run out
          // naturally (which may have already fired while hidden).
        }
        return;
      }
      // Once the warning is showing, ambient activity (pointermove, scroll,
      // even a stray keydown/pointerdown while nobody's actually reading
      // the modal) must NOT silently reset the timer — the whole point of
      // this warning is requiring a deliberate confirmation before
      // extending an unattended session. The modal is a full-screen
      // overlay, so nothing legitimate is blocked by ignoring these here:
      // the only real interaction available is its own "Stay Logged In"
      // button, which calls resetTimer directly, bypassing this check.
      if (warningVisibleRef.current) return;
      resetTimer();
    };

    events.forEach(e => window.addEventListener(e, handleActivity, { passive: true }));
    resetTimer();
    return () => {
      events.forEach(e => window.removeEventListener(e, handleActivity));
      clearTimeout(timerRef.current);
      clearTimeout(warnTimerRef.current);
      clearInterval(countdownRef.current);
    };
  }, [user?.id, resetTimer]); // resetTimer is now stable (no deps)

  return { warningVisible, secondsLeft, resetTimer };
}

function SessionWarningModal({ secondsLeft, onStayLoggedIn, onLogout }) {
  const mins = Math.floor(secondsLeft / 60);
  const secs = secondsLeft % 60;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.75)", zIndex: 9999, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.amber}`, borderRadius: 10, padding: 24, maxWidth: 360, width: "100%", display: "flex", flexDirection: "column", gap: 14, textAlign: "center" }}>
        <div style={{ fontSize: 32 }}>⏱</div>
        <div style={{ fontFamily: FONTS.head, fontSize: 18, fontWeight: 800, color: COLORS.chalk }}>
          Still there?
        </div>
        <div style={{ fontSize: 13, color: COLORS.ghost }}>
          You'll be logged out in{" "}
          <span style={{ color: COLORS.amber, fontWeight: 700 }}>
            {mins > 0 ? `${mins}m ${secs}s` : `${secs}s`}
          </span>{" "}
          due to inactivity.
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <Button title="LOG OUT NOW" variant="ghost" style={{ flex: 1 }} onClick={onLogout} />
          <Button title="STAY LOGGED IN" variant="amber" style={{ flex: 2 }} onClick={onStayLoggedIn} />
        </div>
      </div>
    </div>
  );
}

// ── Live trip sharing ─────────────────────────────────────────────────────
// Generates a public share URL for a trip. The URL contains a one-way
// token (not the trip ID) so it can be shared without exposing system IDs.
// Token is generated at driver confirmation and stored on the trip.
// The public viewer page reads driver GPS via Supabase Realtime (no auth).
// NOTE: The public /share/:token page is a separate deployment concern —
// this generates the token and the URL. The agent UI hook is intentionally
// NOT added yet (per spec). Accessible from admin trip details for testing.
function generateShareToken() {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return Array.from(bytes).map(b => b.toString(16).padStart(2, "0")).join("");
}

function buildShareUrl(token) {
  return `${window.location.origin}/share/${token}`;
}

function copyShareLink(trip, dispatch) {
  if (!trip.share_token) {
    // Generate and save token
    const token = generateShareToken();
    dispatch({ type: "TRIP/SET_SHARE_TOKEN", trip_id: trip.trip_id, token })
      .then(() => {
        navigator.clipboard.writeText(buildShareUrl(token))
          .catch(() => {});
      })
      .catch(() => {});
    return;
  }
  navigator.clipboard.writeText(buildShareUrl(trip.share_token)).catch(() => {});
}

// ── Offline mode — action queue ───────────────────────────────────────────
// When a driver is offline, critical actions (pickup/dropoff confirmations)
// are queued to localStorage and replayed when connectivity returns.
// This prevents drivers losing confirmation data when signal drops mid-route.
const OFFLINE_QUEUE_KEY = "transitos_offline_queue";

function getOfflineQueue() {
  try { return JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY) || "[]"); } catch { return []; }
}
function setOfflineQueue(q) {
  try { localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(q)); } catch {}
}
// navigator.onLine only reflects whether a network interface is
// associated — it stays true during a weak/spotty signal, which is
// exactly the real-world case this queue exists for (a moving vehicle,
// not a toggled airplane mode). A failed dispatch whose error looks
// network-shaped (rather than a real server-side rejection) should be
// queued too, not just surfaced as a one-shot error the driver must
// notice and manually retry.
function isNetworkError(e) {
  return e instanceof TypeError || /fetch|network|failed to connect/i.test(e?.message || "");
}
function enqueueOfflineAction(action) {
  const q = getOfflineQueue();
  q.push({ ...action, _queuedAt: Date.now() });
  setOfflineQueue(q);
  console.log(`[Offline] Queued: ${action.type} (queue depth: ${q.length})`);
}

// Hook that tracks online status and auto-replays the queue on reconnect
function useOfflineSync(dispatch) {
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);
  const [syncing, setSyncing] = React.useState(false);
  const [syncResult, setSyncResult] = React.useState(null); // { replayed, failed }

  React.useEffect(() => {
    const goOnline = async () => {
      setIsOnline(true);
      // Queued-Waze-nav replay was removed along with the external Waze
      // handoff itself — navigation now happens entirely in-app
      // (DriverNavMap), which handles "no connection yet" on its own via
      // its own error/retry state rather than needing an offline queue.
      const q = getOfflineQueue();
      if (q.length === 0) return;
      setSyncing(true);
      let replayed = 0, failed = 0;
      // Keep failed actions queued instead of unconditionally clearing —
      // a replay failure (flaky reconnect, one bad request) used to
      // permanently delete a driver's pickup/dropoff confirmation with no
      // retry, defeating the entire point of this queue.
      const stillPending = [];
      let notYetProcessed = q;
      for (const action of q) {
        notYetProcessed = notYetProcessed.slice(1);
        try {
          await dispatch(action);
          replayed++;
        } catch (e) {
          console.warn(`[Offline] Replay failed for ${action.type}:`, e.message);
          failed++;
          stillPending.push(action);
        }
        // Persist after EVERY item, not just once after the whole loop —
        // this hook runs in a moving vehicle with flaky signal; if the
        // tab/PWA gets backgrounded or killed mid-replay, localStorage
        // must already reflect what's actually still pending. Persisting
        // only once at the end meant an interrupted replay left the
        // ORIGINAL full queue in storage, including items that had
        // already succeeded — the next reconnect would replay them a
        // second time, silently overwriting a correct pickup/dropoff
        // timestamp+GPS with a new, later, wrong pair.
        setOfflineQueue([...stillPending, ...notYetProcessed]);
      }
      setSyncing(false);
      setSyncResult({ replayed, failed });
      setTimeout(() => setSyncResult(null), 5000);
    };
    const goOffline = () => setIsOnline(false);
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    return () => { window.removeEventListener("online", goOnline); window.removeEventListener("offline", goOffline); };
  }, [dispatch]);

  return { isOnline, syncing, syncResult };
}

function OfflineBanner({ isOnline, syncing, syncResult }) {
  if (isOnline && !syncing && !syncResult) return null;
  if (syncing) return (
    <div style={{ position: "sticky", top: 0, zIndex: 50, background: COLORS.amber, color: COLORS.ink, padding: "6px 14px", fontSize: 10, fontWeight: 700, textAlign: "center" }}>
      ⟳ BACK ONLINE — Syncing offline actions…
    </div>
  );
  if (syncResult) return (
    <div style={{ position: "sticky", top: 0, zIndex: 50, background: syncResult.failed === 0 ? COLORS.green : COLORS.amber, color: syncResult.failed === 0 ? COLORS.ink : COLORS.ink, padding: "6px 14px", fontSize: 10, fontWeight: 700, textAlign: "center" }}>
      ✓ Synced {syncResult.replayed} offline action{syncResult.replayed !== 1 ? "s" : ""}{syncResult.failed > 0 ? ` — ${syncResult.failed} failed` : ""}
    </div>
  );
  if (!isOnline) return (
    <div style={{ position: "sticky", top: 0, zIndex: 50, background: COLORS.red, color: "#fff", padding: "6px 14px", fontSize: 10, fontWeight: 700, textAlign: "center", letterSpacing: 0.5 }}>
      ⚠ NO INTERNET — Confirmations will be queued and sent when back online
    </div>
  );
  return null;
}

// ── Two-way agent feedback ────────────────────────────────────────────────
// Appears on the agent's completed trip card. One submission per trip per agent.
function TripRatingPrompt({ trip, user, dispatch }) {
  const myRating = trip.agent_ratings?.[user.id];
  const [hovered, setHovered] = React.useState(0);
  const [selected, setSelected] = React.useState(myRating?.stars || 0);
  const [note, setNote] = React.useState("");
  const [submitted, setSubmitted] = React.useState(!!myRating);
  const [submitting, setSubmitting] = React.useState(false);

  if (submitted || myRating) {
    return (
      <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 4 }}>
        {"⭐".repeat(myRating?.stars || selected)} — Thank you for your feedback.
      </div>
    );
  }

  const submit = async (stars) => {
    setSelected(stars);
    setSubmitting(true);
    try {
      await dispatch({ type: "TRIP/RATE", trip_id: trip.trip_id, agent_id: user.id, stars, note: note.trim() || null });
      setSubmitted(true);
    } catch (e) {
      console.warn("Rating failed:", e.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={{ marginTop: 8, padding: "8px 10px", background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4 }}>
      <div style={{ fontSize: 10, color: COLORS.chalk, fontWeight: 700, marginBottom: 6 }}>Rate your trip</div>
      <div style={{ display: "flex", gap: 6, marginBottom: 6 }}>
        {[1,2,3,4,5].map(s => (
          <span key={s} onMouseEnter={() => setHovered(s)} onMouseLeave={() => setHovered(0)}
            onClick={() => !submitting && submit(s)}
            style={{ fontSize: 22, cursor: submitting ? "default" : "pointer", opacity: submitting ? 0.5 : 1,
              filter: (hovered || selected) >= s ? "none" : "grayscale(1) opacity(0.4)" }}>⭐</span>
        ))}
      </div>
    </div>
  );
}

// Average star rating for a driver across all rated trips
function driverAvgRating(driverId, allTrips) {
  const ratings = [];
  for (const t of allTrips) {
    if (String(t.driver_id) !== String(driverId)) continue;
    for (const r of Object.values(t.agent_ratings || {})) {
      if (r?.stars) ratings.push(r.stars);
    }
  }
  if (ratings.length === 0) return null;
  return { avg: ratings.reduce((a, b) => a + b, 0) / ratings.length, count: ratings.length };
}

// ── Capacity forecasting ──────────────────────────────────────────────────
// Groups historical completed trips by day-of-week + hour bucket, then
// predicts how many passengers to expect for a given future date+time.
// Returns { predicted: N, confidence: "HIGH"|"MEDIUM"|"LOW", sampleSize: N }
function forecastDemand(allTrips, targetDateStr, targetTimeStr) {
  if (!targetDateStr || !targetTimeStr) return null;
  const parts = targetDateStr.split("/").map(Number);
  const targetDate = new Date(parts[0], parts[1] - 1, parts[2]);
  const targetDow = targetDate.getDay();
  const [th] = targetTimeStr.split(":").map(Number);
  // Find historical completed trips on same day-of-week within ±1 hour
  const historical = allTrips.filter(t => {
    if (t.state !== TRIP_STATE.ARCHIVED_COMPLETED) return false;
    if (!t.scheduled_date || !t.scheduled_time) return false;
    const p = t.scheduled_date.split("/").map(Number);
    const d = new Date(p[0], p[1] - 1, p[2]);
    if (d.getDay() !== targetDow) return false;
    const rawTime = t.scheduled_time_str || t.scheduled_time || "";
    const rawStr = String(rawTime);
    // If it looks like an epoch (all digits, > 4 chars), convert to HH:MM
    const timeVal = /^\d{10,}$/.test(rawStr.trim())
      ? new Date(Number(rawStr)).toTimeString().slice(0, 5)
      : rawStr;
    const h = parseInt(timeVal.split(":")[0], 10);
    return !isNaN(h) && Math.abs(h - th) <= 1;
  });
  if (historical.length === 0) return { predicted: null, confidence: "LOW", sampleSize: 0 };
  const totalPax = historical.reduce((n, t) => n + (t.agent_ids?.length || 1), 0);
  const predicted = Math.round(totalPax / historical.length);
  const confidence = historical.length >= 8 ? "HIGH" : historical.length >= 4 ? "MEDIUM" : "LOW";
  return { predicted, confidence, sampleSize: historical.length };
}

function CapacityForecastPanel({ state }) {
  // Show forecast for the next 7 days at common time slots
  const slots = [];
  const now = new Date();
  for (let d = 1; d <= 7; d++) {
    const date = new Date(now);
    date.setDate(date.getDate() + d);
    const dateStr = `${date.getFullYear()}/${String(date.getMonth()+1).padStart(2,"0")}/${String(date.getDate()).padStart(2,"0")}`;
    const dayName = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][date.getDay()];
    for (const time of ["06:00","07:00","17:00","18:00","21:00"]) {
      const f = forecastDemand(state.trips || [], dateStr, time);
      if (f?.predicted > 0) {
        const driversNeeded = Math.ceil(f.predicted / DRIVER_CAPACITY);
        slots.push({ dateStr, dayName, time, ...f, driversNeeded });
      }
    }
  }
  if (slots.length === 0) return (
    <div style={{ fontSize: 10, color: COLORS.ghost }}>Not enough historical data yet — forecasts appear after 4+ completed trips per time slot.</div>
  );
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      {slots.map((s, i) => {
        const confColor = s.confidence === "HIGH" ? COLORS.green : s.confidence === "MEDIUM" ? COLORS.amber : COLORS.ghost;
        return (
          <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 10px", background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4 }}>
            <div>
              <span style={{ fontSize: 11, fontWeight: 700, color: COLORS.chalk }}>{s.dayName} {s.dateStr} @ {s.time}</span>
              <span style={{ fontSize: 9, color: confColor, marginLeft: 8 }}>{s.confidence} confidence ({s.sampleSize} historical runs)</span>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 13, fontWeight: 800, color: COLORS.amber, fontFamily: FONTS.head }}>{s.predicted} pax</div>
              <div style={{ fontSize: 9, color: COLORS.ghost }}>{s.driversNeeded} driver{s.driversNeeded !== 1 ? "s" : ""} needed</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── Driver shift scheduling ───────────────────────────────────────────────
// availability_schedule on driver_status: array of
// { day: 0-6 (Sun=0), start: "HH:MM", end: "HH:MM" }
// "HH:MM" is 24h format. Empty array = always available (backward compat).
function isDriverOnShift(ds, scheduledDateStr, scheduledTimeStr) {
  const schedule = ds.availability_schedule;
  if (!schedule || schedule.length === 0) return true; // no schedule = always available
  if (!scheduledDateStr || !scheduledTimeStr) return true; // no trip time = show driver
  // Parse scheduled date into a JS Date to get day-of-week
  const parts = scheduledDateStr.split("/").map(Number); // YYYY/MM/DD
  const tripDate = new Date(parts[0], parts[1] - 1, parts[2]);
  const tripDow = tripDate.getDay(); // 0=Sun
  // Parse trip time "HH:MM"
  const [tripH, tripM] = scheduledTimeStr.split(":").map(Number);
  const tripMins = tripH * 60 + tripM;
  return schedule.some(slot => {
    const [sh, sm] = slot.start.split(":").map(Number);
    const [eh, em] = slot.end.split(":").map(Number);
    const startMins = sh * 60 + sm;
    const endMins = eh * 60 + em;
    if (endMins >= startMins) {
      // Normal same-day shift.
      return slot.day === tripDow && tripMins >= startMins && tripMins <= endMins;
    }
    // Shift crosses midnight (e.g. start:"22:00", end:"02:00" — a
    // perfectly normal night shift). endMins < startMins used to make
    // `tripMins >= startMins && tripMins <= endMins` impossible to
    // satisfy for ANY minute of the day, so a night-shift driver was
    // silently treated as off-shift for their entire actual shift,
    // including hours they explicitly configured as available —
    // excluded from real dispatch candidate lists and undercounted in
    // staffing-gap forecasts. A midnight-crossing shift actually covers
    // two segments: the late-night portion on slot.day itself, and the
    // early-morning portion on the calendar day AFTER slot.day.
    const nextDow = (slot.day + 1) % 7;
    return (slot.day === tripDow && tripMins >= startMins)
        || (nextDow === tripDow && tripMins <= endMins);
  });
}

const DAYS_OF_WEEK = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function DriverShiftEditor({ ds, dispatch, onClose }) {
  const existing = ds.availability_schedule || [];
  const [slots, setSlots] = React.useState(existing.length > 0 ? existing : []);
  const [saving, setSaving] = React.useState(false);
  const [err, setErr] = React.useState(null);

  const addSlot = () => setSlots(s => [...s, { day: 1, start: "06:00", end: "22:00" }]);
  const removeSlot = (i) => setSlots(s => s.filter((_, idx) => idx !== i));
  const updateSlot = (i, key, val) => setSlots(s => s.map((sl, idx) => idx === i ? { ...sl, [key]: val } : sl));

  const save = async () => {
    setSaving(true);
    try {
      await dispatch({ type: "DRIVER/SET_SHIFT_SCHEDULE", driver_id: ds.driver_id, schedule: slots });
      onClose();
    } catch (e) {
      setErr(e.message || "Failed to save shift schedule");
      setSaving(false);
    }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", zIndex: 1000, display: "flex", alignItems: "flex-end", justifyContent: "center" }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div style={{ width: "100%", maxWidth: 480, background: COLORS.panel, borderTopLeftRadius: 12, borderTopRightRadius: 12, border: `1px solid ${COLORS.wire}`, borderBottom: "none", padding: 20, display: "flex", flexDirection: "column", gap: 12, maxHeight: "80vh", overflowY: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: COLORS.amber, letterSpacing: 1 }}>⏱ SHIFT SCHEDULE</span>
          <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.ghost, fontSize: 16, cursor: "pointer" }}>✕</button>
        </div>
        <div style={{ fontSize: 10, color: COLORS.ghost }}>
          Leave empty = always available. Add blocks for specific days and hours.
        </div>
        {slots.map((sl, i) => (
          <div key={i} style={{ display: "flex", gap: 6, alignItems: "center", background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: 8 }}>
            <select value={sl.day} onChange={e => updateSlot(i, "day", +e.target.value)}
              style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, color: COLORS.chalk, borderRadius: 3, padding: "4px 6px", fontSize: 11 }}>
              {DAYS_OF_WEEK.map((d, idx) => <option key={idx} value={idx}>{d}</option>)}
            </select>
            <input type="time" value={sl.start} onChange={e => updateSlot(i, "start", e.target.value)}
              style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, color: COLORS.chalk, borderRadius: 3, padding: "4px 6px", fontSize: 11, flex: 1 }} />
            <span style={{ fontSize: 10, color: COLORS.ghost }}>to</span>
            <input type="time" value={sl.end} onChange={e => updateSlot(i, "end", e.target.value)}
              style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, color: COLORS.chalk, borderRadius: 3, padding: "4px 6px", fontSize: 11, flex: 1 }} />
            <button onClick={() => removeSlot(i)} style={{ background: "none", border: "none", color: COLORS.red, fontSize: 14, cursor: "pointer", flexShrink: 0 }}>✕</button>
          </div>
        ))}
        <Button title="+ ADD SHIFT BLOCK" variant="ghost" onClick={addSlot} full />
        {err && <div style={{ fontSize: 10, color: COLORS.red }}>{err}</div>}
        <div style={{ display: "flex", gap: 8 }}>
          <Button title="CANCEL" variant="ghost" style={{ flex: 1 }} onClick={onClose} disabled={saving} />
          <Button title={saving ? "SAVING…" : "✓ SAVE SCHEDULE"} variant="amber" style={{ flex: 1 }} onClick={save} disabled={saving} />
        </div>
      </div>
    </div>
  );
}

// ── Driver performance stats ─────────────────────────────────────────────
// Computed from trip history. Returned object used in AdminDrivers panel.
function computeDriverStats(driverId, allTrips) {
  const mine = allTrips.filter(t => String(t.driver_id) === String(driverId));
  const completed = mine.filter(t => t.state === TRIP_STATE.ARCHIVED_COMPLETED).length;
  const cancelled = mine.filter(t => t.state === TRIP_STATE.ARCHIVED_CANCELLED).length;
  const total = mine.length;
  const completionRate = total > 0 ? (completed / total) : null;
  const rejections = allTrips.filter(t => (t.declinedBy || []).some(id => String(id) === String(driverId))).length;
  const noShowTrips = mine.filter(t => t.no_shows && t.no_shows.length > 0).length;
  // Avg passengers per completed trip
  const avgPassengers = completed > 0
    ? mine.filter(t => t.state === TRIP_STATE.ARCHIVED_COMPLETED)
        .reduce((sum, t) => sum + (t.agent_ids?.length || 1), 0) / completed
    : null;
  return { completed, cancelled, total, completionRate, rejections, noShowTrips, avgPassengers };
}




// ── SOS / Emergency button ────────────────────────────────────────────────
// One tap → confirms intent → fires admin alert with GPS + trip context.
// Requires two taps to avoid accidental triggers (confirm step).
// Matches South African transport operator compliance requirements.
function SOSButton({ user, tripId, driverName, dispatch }) {
  const [armed, setArmed] = React.useState(false);
  const [sent, setSent] = React.useState(false);
  // Was silently swallowed via `.catch(() => {})` with `sent` set BEFORE
  // the dispatch even ran — meaning a network failure at the exact
  // moment someone in a real emergency hit CONFIRM SOS showed them
  // "🚨 SOS SENT — Operations has been alerted" regardless of whether
  // anyone was actually alerted, with no way to know it hadn't gone
  // through. `queued` (network-shaped failure, auto-retries via the
  // existing offline queue) and `sendError` (a real rejection, needs a
  // manual retry) are now both honestly distinguished from a confirmed send.
  const [queued, setQueued] = React.useState(false);
  const [sendError, setSendError] = React.useState(null);
  const [armTimeout, setArmTimeout] = React.useState(null);

  const arm = () => {
    setArmed(true);
    const t = setTimeout(() => setArmed(false), 5000); // auto-disarm after 5s
    setArmTimeout(t);
  };

  const fire = async () => {
    if (armTimeout) clearTimeout(armTimeout);
    setArmed(false);
    setSendError(null);
    // Get GPS if available
    let gpsStr = "GPS unavailable";
    try {
      await new Promise((res, rej) => navigator.geolocation.getCurrentPosition(
        pos => { gpsStr = pos.coords.latitude.toFixed(5) + "," + pos.coords.longitude.toFixed(5); res(); },
        () => res(), { timeout: 3000 }
      ));
    } catch {}
    const mapsLink = gpsStr !== "GPS unavailable"
      ? " https://maps.google.com/?q=" + gpsStr : "";
    const sosAction = {
      type: "SYSTEM/SOS_ALERT",
      sender_id: user.id, sender_name: user.name,
      trip_id: tripId || null,
      driver_name: driverName || null,
      gps: gpsStr,
      message: "🚨 SOS — " + user.name + " (" + user.role + ") triggered emergency alert on trip " + (tripId || "unknown") + ". GPS: " + gpsStr + "." + mapsLink + " Immediate attention required.",
    };
    try {
      await dispatch(sosAction);
      setSent(true);
      setTimeout(() => setSent(false), 10000);
    } catch (e) {
      if (isNetworkError(e)) {
        enqueueOfflineAction(sosAction);
        setQueued(true);
      } else {
        setSendError(e.message || "Couldn't send the alert — please try again.");
      }
    }
  };

  if (sent) return (
    <div style={{ background: "rgba(220,53,69,0.12)", border: "1px solid rgba(220,53,69,0.5)", borderRadius: 6, padding: "10px 14px", textAlign: "center" }}>
      <div style={{ fontSize: 12, fontWeight: 800, color: COLORS.red }}>🚨 SOS SENT</div>
      <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>Operations has been alerted with your location.</div>
    </div>
  );

  if (queued) return (
    <div style={{ background: "rgba(245,166,35,0.12)", border: `1px solid ${COLORS.amber}`, borderRadius: 6, padding: "10px 14px", textAlign: "center" }}>
      <div style={{ fontSize: 12, fontWeight: 800, color: COLORS.amber }}>⚠ NO SIGNAL — SOS QUEUED</div>
      <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>Will send the instant you're back online. If this is a real emergency, please also call for help directly.</div>
    </div>
  );

  if (sendError) return (
    <div style={{ background: "rgba(220,53,69,0.12)", border: `1px solid ${COLORS.red}`, borderRadius: 6, padding: "10px 14px", textAlign: "center", display: "flex", flexDirection: "column", gap: 6 }}>
      <div style={{ fontSize: 11, fontWeight: 800, color: COLORS.red }}>✗ SOS NOT SENT — {sendError}</div>
      <button onClick={fire}
        style={{ background: COLORS.red, border: "none", borderRadius: 5, padding: 10, cursor: "pointer", color: "#fff", fontSize: 12, fontWeight: 800 }}>
        🚨 TRY AGAIN
      </button>
    </div>
  );

  if (armed) return (
    <div style={{ display: "flex", gap: 8 }}>
      <button onClick={() => { setArmed(false); clearTimeout(armTimeout); }}
        style={{ flex: 1, background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 5, padding: 10, cursor: "pointer", color: COLORS.chalk, fontSize: 11, fontWeight: 700 }}>
        CANCEL
      </button>
      <button onClick={fire}
        style={{ flex: 2, background: COLORS.red, border: "none", borderRadius: 5, padding: 10, cursor: "pointer", color: "#fff", fontSize: 12, fontWeight: 800, animation: "pulse 0.8s infinite" }}>
        🚨 CONFIRM SOS
      </button>
    </div>
  );

  return (
    <button onClick={arm}
      style={{ width: "100%", background: "rgba(220,53,69,0.08)", border: `2px solid ${COLORS.red}`, borderRadius: 6, padding: 10, cursor: "pointer", color: COLORS.red, fontSize: 11, fontWeight: 800, letterSpacing: 0.5 }}>
      🚨 SOS / EMERGENCY
    </button>
  );
}

// ── In-app Waze navigation panel ─────────────────────────────────────────
// Professional fleet apps can't actually embed Waze (Waze blocks iframes
// and cross-origin embedding). What they DO is a persistent nav panel
// that shows: current stop details, one-tap launch into Waze pre-loaded
// with the destination, and trip progress — so it FEELS embedded.
// This is the same technique Bolt and inDriver use on Android/iOS.
function WazeNavPanel({ trip, user, state, setNavTarget }) {
  if (!trip) return null;
  const agentIds = trip.agent_ids || [];
  // completed_pickups/completed_dropoffs are arrays of agent IDs who were confirmed
  const completedPickups = trip.completed_pickups || trip.completedpickups || [];
  const completedDropoffs = trip.completed_dropoffs || trip.completeddropoffs || [];

  // Build the ordered sequence of remaining stops
  const remaining = [];
  for (const coord of (trip.pickup_sequence_coords || [])) {
    if (!completedPickups.some(c => String(c) === String(coord.agent_id))) {
      const agent = state.users.find(u => String(u.id) === String(coord.agent_id));
      remaining.push({ type: "PICKUP", coord, agentName: agent?.name || "Passenger", agentId: coord.agent_id });
    }
  }
  for (const coord of (trip.dropoff_sequence_coords || [])) {
    if (completedPickups.some(c => String(c) === String(coord.agent_id)) && !completedDropoffs.some(c => String(c) === String(coord.agent_id))) {
      const agent = state.users.find(u => String(u.id) === String(coord.agent_id));
      remaining.push({ type: "DROPOFF", coord, agentName: agent?.name || "Passenger", agentId: coord.agent_id });
    }
  }

  const current = remaining[0] || null;
  const totalStops = agentIds.length * 2;
  const doneStops = completedPickups.length + completedDropoffs.length;
  const pct = totalStops > 0 ? Math.round((doneStops / totalStops) * 100) : 0;

  return (
    <div style={{ background: COLORS.panel, border: `1px solid ${COLORS.wire}`, borderRadius: 8, padding: 14, display: "flex", flexDirection: "column", gap: 10 }}>
      {/* Progress bar */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 10, fontWeight: 700, color: COLORS.chalk, letterSpacing: 0.5 }}>ROUTE PROGRESS</span>
        <span style={{ fontSize: 10, color: COLORS.amber, fontWeight: 700 }}>{doneStops}/{totalStops} stops</span>
      </div>
      <div style={{ height: 6, background: COLORS.surface, borderRadius: 3, overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${pct}%`, background: COLORS.green, borderRadius: 3, transition: "width 0.4s ease" }} />
      </div>

      {/* Current stop */}
      {current ? (
        <div style={{ background: current.type === "PICKUP" ? "rgba(245,166,35,0.08)" : "rgba(29,185,84,0.08)",
          border: `1px solid ${current.type === "PICKUP" ? "rgba(245,166,35,0.3)" : "rgba(29,185,84,0.3)"}`,
          borderRadius: 6, padding: 12 }}>
          <div style={{ fontSize: 9, fontWeight: 700, letterSpacing: 1,
            color: current.type === "PICKUP" ? COLORS.amber : COLORS.green }}>
            {current.type === "PICKUP" ? "⬆ NEXT PICKUP" : "⬇ NEXT DROPOFF"}
          </div>
          <div style={{ fontSize: 14, fontWeight: 800, color: COLORS.chalk, marginTop: 4, fontFamily: FONTS.head }}>
            {current.agentName}
          </div>
          <div style={{ fontSize: 10, color: COLORS.ghost, marginTop: 2 }}>
            {current.coord.label || "Address not available"}
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
            <button onClick={() => setNavTarget({ lat: current.coord.lat, lng: current.coord.lng, label: current.coord.label, isManual: false })}
              style={{ flex: 1, background: "#00CCFF", border: "none", borderRadius: 5, padding: "10px 0",
                fontWeight: 800, fontSize: 12, cursor: "pointer", color: "#000", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
              <span style={{ fontSize: 16 }}>🗺</span> NAVIGATE
            </button>
            {remaining.length > 1 && (
              <div style={{ flex: 1, background: COLORS.surface, border: `1px solid ${COLORS.wire}`,
                borderRadius: 5, padding: "10px 8px", fontSize: 9, color: COLORS.ghost, display: "flex", flexDirection: "column", justifyContent: "center" }}>
                <div style={{ fontWeight: 700, color: COLORS.chalk, fontSize: 10 }}>AFTER THIS</div>
                <div>{remaining[1]?.type === "PICKUP" ? "⬆" : "⬇"} {remaining[1]?.agentName}</div>
              </div>
            )}
          </div>
        </div>
      ) : (
        <div style={{ textAlign: "center", padding: 16, color: COLORS.green, fontWeight: 700, fontSize: 13 }}>
          ✓ All stops complete
        </div>
      )}

      {/* Remaining stops list */}
      {remaining.length > 1 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          <div style={{ fontSize: 9, color: COLORS.ghost, fontWeight: 700, letterSpacing: 0.5 }}>UPCOMING STOPS</div>
          {remaining.slice(1).map((stop, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "5px 8px",
              background: COLORS.surface, borderRadius: 4, fontSize: 10 }}>
              <span style={{ color: stop.type === "PICKUP" ? COLORS.amber : COLORS.green, fontWeight: 700 }}>
                {stop.type === "PICKUP" ? "⬆" : "⬇"}
              </span>
              <span style={{ color: COLORS.chalk }}>{stop.agentName}</span>
              <span style={{ color: COLORS.ghost, fontSize: 9, marginLeft: "auto" }}>{stop.coord.label?.split(",")[0]}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}





// ── Automated backup verification ────────────────────────────────────────
// Supabase handles physical DB backups automatically (daily on Pro/Team).
// This adds: (1) a verify-connection health check that confirms Supabase
// is reachable and the trips table is readable, (2) a last-verified
// timestamp on the dashboard, and (3) an automated weekly reminder to
// ops to check their Supabase backup settings.
// Note: True offsite backup scheduling (pg_dump → S3) requires a
// Supabase Edge Function or external cron — this is the in-app layer.
const BACKUP_VERIFY_KEY = "transitos_last_backup_verify";

async function verifyDatabaseConnection() {
  const start = Date.now();
  try {
    if (!supabase) throw new Error("Supabase not configured");
    const { data, error } = await supabase
      .from("trips")
      .select("id")
      .limit(1);
    if (error) throw error;
    const ms = Date.now() - start;
    const result = { ok: true, ms, checkedAt: Date.now(), tripCount: null };
    // Also get a count to verify read access is real
    const { count } = await supabase.from("trips").select("*", { count: "exact", head: true });
    result.tripCount = count;
    try { localStorage.setItem(BACKUP_VERIFY_KEY, JSON.stringify(result)); } catch {}
    return result;
  } catch (e) {
    const result = { ok: false, error: e.message, checkedAt: Date.now() };
    try { localStorage.setItem(BACKUP_VERIFY_KEY, JSON.stringify(result)); } catch {}
    return result;
  }
}

function BackupVerifyPanel() {
  const [last, setLast] = React.useState(() => {
    try { return JSON.parse(localStorage.getItem(BACKUP_VERIFY_KEY) || "null"); } catch { return null; }
  });
  const [checking, setChecking] = React.useState(false);

  const check = async () => {
    setChecking(true);
    const result = await verifyDatabaseConnection();
    setLast(result);
    setChecking(false);
  };

  const age = last ? Math.round((Date.now() - last.checkedAt) / 60000) : null;
  const ageStr = age == null ? "Never checked" : age < 60 ? `${age}m ago` : age < 1440 ? `${Math.round(age/60)}h ago` : `${Math.round(age/1440)}d ago`;

  return (
    <div style={{ background: "rgba(29,185,84,0.05)", border: `1px solid ${last?.ok === false ? "rgba(220,53,69,0.4)" : "rgba(29,185,84,0.2)"}`, borderRadius: 6, padding: "10px 14px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 700, color: COLORS.green }}>🛡 DATABASE HEALTH CHECK</div>
          <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>
            {last == null && "Not yet verified this session."}
            {last?.ok === true && `✓ Connected — ${last.tripCount != null ? last.tripCount + " trips" : ""} — ${last.ms}ms — ${ageStr}`}
            {last?.ok === false && `✗ Error: ${last.error} — ${ageStr}`}
          </div>
          <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>
            Physical backups managed by Supabase. Check your project dashboard → Settings → Backups for schedule.
          </div>
        </div>
        <Button title={checking ? "CHECKING…" : "▶ RUN CHECK"} variant="ghost" size="sm"
          style={{ borderColor: COLORS.green, color: COLORS.green, flexShrink: 0 }}
          onClick={check} disabled={checking} />
      </div>
    </div>
  );
}

// ── Driver document expiry tracking ──────────────────────────────────────
// Tracks PrDP (Professional Driving Permit), vehicle licence disc, and
// roadworthy certificate expiry dates. Alerts ops 30 days before expiry
// and flags expired docs on dispatch driver cards.
// Stored on driver_status.documents: { prdp: "YYYY-MM-DD", licence: "...", roadworthy: "..." }
const DOC_TYPES = [
  { key: "prdp",       label: "PrDP",             required: true },
  { key: "licence",    label: "Vehicle Licence",   required: true },
  { key: "roadworthy", label: "Roadworthy Cert",   required: false },
];
const DOC_WARN_DAYS = 30;

function docExpiryStatus(dateStr) {
  if (!dateStr) return { status: "missing", daysLeft: null };
  const expiry = new Date(dateStr);
  const now = new Date();
  const daysLeft = Math.ceil((expiry - now) / (1000 * 60 * 60 * 24));
  if (daysLeft < 0) return { status: "expired", daysLeft };
  if (daysLeft <= DOC_WARN_DAYS) return { status: "expiring", daysLeft };
  return { status: "ok", daysLeft };
}

function DriverDocSummary({ ds }) {
  const docs = ds.documents || {};
  const issues = DOC_TYPES.map(d => ({ ...d, ...docExpiryStatus(docs[d.key]), date: docs[d.key] }))
    .filter(d => d.status !== "ok");
  if (issues.length === 0) return (
    <span style={{ fontSize: 8, color: COLORS.green, fontWeight: 700 }}>✓ DOCS OK</span>
  );
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
      {issues.map(d => (
        <span key={d.key} style={{ fontSize: 8, fontWeight: 700, color: d.status === "expired" ? COLORS.red : COLORS.amber }}>
          {d.status === "expired" ? "✗" : "⚠"} {d.label}: {d.status === "missing" ? "NOT SET" : d.status === "expired" ? `EXPIRED ${Math.abs(d.daysLeft)}d ago` : `expires in ${d.daysLeft}d`}
        </span>
      ))}
    </div>
  );
}

function DriverDocEditor({ ds, dispatch, onClose }) {
  const existing = ds.documents || {};
  const [docs, setDocs] = React.useState({ prdp: existing.prdp || "", licence: existing.licence || "", roadworthy: existing.roadworthy || "" });
  const [saving, setSaving] = React.useState(false);

  const save = async () => {
    setSaving(true);
    try {
      await dispatch({ type: "DRIVER/SET_DOCUMENTS", driver_id: ds.driver_id, documents: docs });
      onClose();
    } catch(e) { setSaving(false); }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.7)", zIndex: 1000, display: "flex", alignItems: "flex-end", justifyContent: "center" }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div style={{ width: "100%", maxWidth: 480, background: COLORS.panel, borderTopLeftRadius: 12, borderTopRightRadius: 12, border: `1px solid ${COLORS.wire}`, borderBottom: "none", padding: 20, display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: COLORS.amber, letterSpacing: 1 }}>📄 DRIVER DOCUMENTS</span>
          <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.ghost, fontSize: 16, cursor: "pointer" }}>✕</button>
        </div>
        {DOC_TYPES.map(d => (
          <div key={d.key}>
            <label style={{ fontSize: 9, fontWeight: 700, color: COLORS.chalk, letterSpacing: 0.5, display: "block", marginBottom: 4 }}>
              {d.label} EXPIRY {d.required ? "*" : ""}
            </label>
            <input type="date" value={docs[d.key]} onChange={e => setDocs(v => ({ ...v, [d.key]: e.target.value }))}
              style={{ width: "100%", background: COLORS.card, border: `1px solid ${docExpiryStatus(docs[d.key]).status === "expired" ? COLORS.red : docExpiryStatus(docs[d.key]).status === "expiring" ? COLORS.amber : COLORS.wire}`, color: COLORS.chalk, borderRadius: 4, padding: "7px 10px", fontSize: 12, boxSizing: "border-box" }} />
            {docs[d.key] && (() => { const s = docExpiryStatus(docs[d.key]); return s.status !== "ok" ? (
              <div style={{ fontSize: 9, color: s.status === "expired" ? COLORS.red : COLORS.amber, marginTop: 2 }}>
                {s.status === "expired" ? "Expired " + Math.abs(s.daysLeft) + " days ago" : "Expires in " + s.daysLeft + " days"}
              </div>
            ) : null; })()}
          </div>
        ))}
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <Button title="CANCEL" variant="ghost" style={{ flex: 1 }} onClick={onClose} disabled={saving} />
          <Button title={saving ? "SAVING…" : "✓ SAVE"} variant="amber" style={{ flex: 1 }} onClick={save} disabled={saving} />
        </div>
      </div>
    </div>
  );
}

// ── Audit export for compliance ───────────────────────────────────────────
// Exports a full audit trail CSV for a date range — every action logged
// against every trip, with actor, timestamp, GPS where captured, and
// exception flags. Suitable for transport regulator submissions and
// insurance claims.
async function exportComplianceAudit(trips, users, auditLogs, fromDateStr, toDateStr, delaysByTrip = {}) {
  const headers = [
    "Trip ID","Date","Time","Direction","Driver","Agent(s)","Status",
    "Exception","Booked At","Driver Assigned At","Driver Accepted At",
    "Trip Started At","Completed At","Rejection Reason","Rejection Note",
    "No-Show Count","Delay Reports","Route km","Audit Actions",
  ];

  // Safely wrap a value for CSV — escape quotes and wrap in quotes if needed
  const csvCell = (v) => {
    if (v == null || v === "") return "";
    const s = String(v);
    if (s.includes(",") || s.includes('"') || s.includes("\n") || s.includes("\r")) {
      return `"${s.replace(/"/g, '""')}"`;
    }
    return s;
  };

  // Type-safe ID comparison — bigint vs string vs number all normalised to string
  const idEq = (a, b) => String(a) === String(b);

  const agentNames = (t) => (t.agent_ids || [])
    .map(id => users.find(u => idEq(u.id, id))?.name || String(id)).join(" | ");
  const driverName = (t) => {
    if (!t.driver_id) return "";
    return users.find(u => idEq(u.id, t.driver_id))?.name || String(t.driver_id);
  };
  const fmtEpoch = (ep) => {
    if (!ep) return "";
    // timeZone pinned explicitly — "en-ZA" only controls the DD/MM/YYYY
    // string FORMAT, not which timezone the epoch is converted through,
    // which otherwise silently follows the exporting device's own OS
    // clock. This export is for regulatory/compliance submissions, so a
    // misconfigured or traveling admin's device must never silently shift
    // every timestamp in the file. Africa/Johannesburg = SAST (UTC+2,
    // no DST), matching Cape Town year-round.
    try { return new Date(Number(ep)).toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" }); } catch { return String(ep); }
  };

  const inRange = trips.filter(t => {
    const d = (t.scheduled_date || "").replace(/\//g, "-");
    const f = fromDateStr.replace(/\//g, "-");
    const to2 = toDateStr.replace(/\//g, "-");
    return d >= f && d <= to2;
  });

  if (inRange.length === 0) {
    alert("No trips found in the selected date range.");
    return;
  }

  // auditLogs from fetchAuditLogsForTrips is a { [tripId]: entries[] } object
  // Normalise to handle both object and array inputs defensively
  const getAuditForTrip = (tripId) => {
    if (!auditLogs) return [];
    if (Array.isArray(auditLogs)) {
      return auditLogs.filter(a => idEq(a.trip_id ?? a.tripid, tripId));
    }
    // Object keyed by tripid (the normal case from fetchAuditLogsForTrips)
    return auditLogs[tripId] || auditLogs[String(tripId)] || [];
  };

  const rows = inRange.map(t => {
    const tripAuditEntries = getAuditForTrip(t.trip_id);
    const auditSummary = tripAuditEntries.map(a =>
      `[${fmtEpoch(a.timestamp)}] ${a.username || a.actor_name || ""}: ${a.actionType || a.action_type || ""}${a.details ? " - " + a.details : ""}`
    ).join(" | ");

    // Trips never carry a `delays` field — real delay/detour reports live
    // in the trip_delays table and must be fetched separately (see
    // fetchDelaysForTrips, already used the same way by the main trip CSV
    // export). This read `t.delays` directly, which is undefined on every
    // trip object in this codebase, so the "Delay Reports" column always
    // silently showed nothing — on a document whose own UI copy explicitly
    // promises delay reports for regulatory submissions.
    const tripDelays = delaysByTrip[t.trip_id] || [];
    const delaySummary = tripDelays.map(d =>
      `${d.reason}${d.note ? ` (${d.note})` : ""} @ ${fmtEpoch(d.reported_at)}`
    ).join(" | ");

    return [
      t.trip_id,
      t.scheduled_date || "",
      t.scheduled_time || "",
      t.direction || "",
      driverName(t),
      agentNames(t),
      t.state || "",
      exceptionLabel(t) || "",
      t.booked_at || "",
      t.confirmed_at || "",
      t.acceptedAt || "",
      t.in_transit_at || "",
      t.completed_at || "",
      t.rejection_reason || "",
      t.rejection_note || "",
      (t.no_shows || []).length,
      delaySummary,
      t.driver_route_km ?? t.est_distance_km ?? "",
      auditSummary,
    ].map(csvCell);
  });

  // Pinned to SAST — see fmtEpoch above for why this document's timestamps
  // can't be allowed to silently follow the exporting device's own clock.
  const now = new Date().toLocaleString("en-ZA", { timeZone: "Africa/Johannesburg" });
  const csvLines = [
    csvCell(`# TransitOS Compliance Audit Export — Generated: ${now}`),
    csvCell(`# Period: ${fromDateStr} to ${toDateStr} — Trips: ${inRange.length}`),
    "# This document constitutes a complete operational audit trail.",
    "",
    headers.join(","),
    ...rows.map(r => r.join(",")),
  ];
  const csv = csvLines.join("\r\n"); // CRLF for Excel compatibility

  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" }); // BOM for Excel
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.setAttribute("download", `compliance_audit_${fromDateStr.replace(/\//g, "-")}_to_${toDateStr.replace(/\//g, "-")}.csv`);
  document.body.appendChild(a); // required for Firefox
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function AuditExportPanel({ state }) {
  const [from, setFrom] = React.useState(() => {
    const d = new Date(); d.setDate(d.getDate() - 30);
    return d.toISOString().slice(0,10);
  });
  const [to, setTo] = React.useState(new Date().toISOString().slice(0,10));
  const [exporting, setExporting] = React.useState(false);

  const doExport = async () => {
    setExporting(true);
    try {
      // Fetch audit logs for all trips in range
      const inRange = state.trips.filter(t => {
        const d = (t.scheduled_date || "").replace(/\//g, "-");
        return d >= from && d <= to;
      });
      const tripIds = inRange.map(t => t.trip_id).filter(Boolean);
      const auditLogs = tripIds.length > 0 ? await fetchAuditLogsForTrips(tripIds) : [];
      const delaysByTrip = tripIds.length > 0 ? await fetchDelaysForTrips(tripIds) : {};
      await exportComplianceAudit(state.trips, state.users, auditLogs, from.replace(/-/g,"/"), to.replace(/-/g,"/"), delaysByTrip);
    } finally {
      setExporting(false);
    }
  };

  return (
    <div style={{ background: "rgba(29,185,84,0.05)", border: "1px solid rgba(29,185,84,0.2)", borderRadius: 6, padding: "10px 14px" }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: COLORS.green, marginBottom: 8 }}>📋 COMPLIANCE AUDIT EXPORT</div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <input type="date" value={from} onChange={e => setFrom(e.target.value)}
          style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, color: COLORS.chalk, borderRadius: 3, padding: "5px 8px", fontSize: 11 }} />
        <span style={{ fontSize: 10, color: COLORS.ghost }}>to</span>
        <input type="date" value={to} onChange={e => setTo(e.target.value)}
          style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, color: COLORS.chalk, borderRadius: 3, padding: "5px 8px", fontSize: 11 }} />
        <Button title={exporting ? "EXPORTING…" : "⬇ EXPORT CSV"} variant="ghost" size="sm"
          style={{ borderColor: COLORS.green, color: COLORS.green }} onClick={doExport} disabled={exporting} />
      </div>
      <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 6 }}>
        Includes all trip actions, GPS timestamps, exceptions, rejections, and delay reports. Suitable for regulatory submissions.
      </div>
    </div>
  );
}

// ── SLA reporting ─────────────────────────────────────────────────────────
// On-time defined as: in_transit_at within 10 min of scheduled epoch.
// Returns per-driver metrics for a given set of completed trips.
const SLA_GRACE_MINUTES = 10;

function computeSlaReport(trips, users) {
  const byDriver = {};
  for (const t of trips) {
    if (t.state !== TRIP_STATE.ARCHIVED_COMPLETED) continue;
    if (!t.driver_id) continue;
    // Use raw epoch fields — in_transit_at and scheduled_time are display
    // strings after tripRowToApp; scheduled_time_epoch and in_transit_at_epoch
    // are the original bigint ms values preserved alongside them.
    const scheduledEpoch = t.scheduled_time_epoch;
    const actualEpoch = t.in_transit_at_epoch;
    if (!scheduledEpoch || !actualEpoch) continue;
    const deltaMin = (Number(actualEpoch) - Number(scheduledEpoch)) / 60000;
    const onTime = deltaMin <= SLA_GRACE_MINUTES;
    if (!byDriver[t.driver_id]) {
      const u = users.find(u => String(u.id) === String(t.driver_id));
      byDriver[t.driver_id] = { name: u?.name || t.driver_id, total: 0, onTime: 0, lateMin: [] };
    }
    byDriver[t.driver_id].total++;
    if (onTime) byDriver[t.driver_id].onTime++;
    else byDriver[t.driver_id].lateMin.push(Math.round(deltaMin));
  }
  return Object.values(byDriver).map(d => ({
    ...d,
    rate: d.total > 0 ? d.onTime / d.total : null,
    avgLateMin: d.lateMin.length > 0 ? Math.round(d.lateMin.reduce((a,b)=>a+b,0)/d.lateMin.length) : 0,
  })).sort((a, b) => (b.rate ?? -1) - (a.rate ?? -1));
}

function SlaReportPanel({ trips, users }) {
  const report = computeSlaReport(trips, users);
  if (report.length === 0) return (
    <div style={{ fontSize: 10, color: COLORS.ghost }}>No completed trips with timing data yet. SLA tracking requires in_transit_at timestamps.</div>
  );
  const overall = report.reduce((acc, d) => ({ total: acc.total + d.total, onTime: acc.onTime + d.onTime }), { total: 0, onTime: 0 });
  const overallRate = overall.total > 0 ? overall.onTime / overall.total : null;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {[
          ["OVERALL ON-TIME", overallRate != null ? Math.round(overallRate*100)+"%" : "—", overallRate >= 0.9 ? COLORS.green : overallRate >= 0.7 ? COLORS.amber : COLORS.red],
          ["TOTAL TRIPS", overall.total, COLORS.chalk],
          ["SLA THRESHOLD", SLA_GRACE_MINUTES+" min", COLORS.ghost],
        ].map(([l,v,c]) => (
          <div key={l} style={{ background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: "6px 12px", minWidth: 90 }}>
            <div style={{ fontSize: 8, color: COLORS.ghost, letterSpacing: 0.8 }}>{l}</div>
            <div style={{ fontSize: 16, fontWeight: 800, color: c, fontFamily: FONTS.head }}>{v}</div>
          </div>
        ))}
      </div>
      {report.map(d => {
        const rateColor = d.rate == null ? COLORS.ghost : d.rate >= 0.9 ? COLORS.green : d.rate >= 0.7 ? COLORS.amber : COLORS.red;
        return (
          <div key={d.name} style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: "8px 12px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <div style={{ fontSize: 12, fontWeight: 700, color: COLORS.chalk }}>{d.name}</div>
              <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>{d.total} trips · {d.lateMin.length} late{d.avgLateMin > 0 ? ` (avg ${d.avgLateMin} min)` : ""}</div>
            </div>
            <div style={{ fontSize: 18, fontWeight: 800, color: rateColor, fontFamily: FONTS.head }}>
              {d.rate != null ? Math.round(d.rate*100)+"%" : "—"}
            </div>
          </div>
        );
      })}
    </div>
  );
}



// ── Smart scheduling recommendations ─────────────────────────────────────
// Looks ahead 7 days: for each day+time slot that historically has demand,
// checks how many drivers are actually rostered. Surfaces gaps where
// historical demand exceeds rostered capacity.
function computeSchedulingRecommendations(trips, driverStatus, companies) {
  const now = new Date();
  const gaps = [];

  // For each of the next 7 days
  for (let d = 1; d <= 7; d++) {
    const date = new Date(now);
    date.setDate(date.getDate() + d);
    const dow = date.getDay(); // 0=Sun
    const dateStr = `${date.getFullYear()}/${String(date.getMonth()+1).padStart(2,"0")}/${String(date.getDate()).padStart(2,"0")}`;
    const dayName = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][dow];

    // Check common time slots
    for (const timeStr of ["06:00","07:00","17:00","18:00","21:00","22:00"]) {
      const [th] = timeStr.split(":").map(Number);
      // Historical demand: completed trips on this dow ± 1h
      const historical = trips.filter(t => {
        if (t.state !== TRIP_STATE.ARCHIVED_COMPLETED) return false;
        if (!t.scheduled_date) return false;
        const p = t.scheduled_date.split("/").map(Number);
        const td = new Date(p[0], p[1]-1, p[2]);
        if (td.getDay() !== dow) return false;
        const rawTimeSched = t.scheduled_time_str || t.scheduled_time || "00:00";
        const rawStrSched = String(rawTimeSched);
        const timeValSched = /^\d{10,}$/.test(rawStrSched.trim())
          ? new Date(Number(rawStrSched)).toTimeString().slice(0, 5) : rawStrSched;
        const h = parseInt(timeValSched.split(":")[0], 10);
        return !isNaN(h) && Math.abs(h - th) <= 1;
      });
      if (historical.length < 3) continue; // need at least 3 data points

      const avgPax = historical.reduce((n, t) => n + (t.agent_ids?.length || 1), 0) / historical.length;
      const driversNeeded = Math.ceil(avgPax / DRIVER_CAPACITY);

      // Count drivers rostered for this slot
      const rosteredCount = (driverStatus || []).filter(ds =>
        isDriverOnShift(ds, dateStr, timeStr) && !ds.is_unavailable
      ).length;

      if (rosteredCount < driversNeeded) {
        gaps.push({
          date: dateStr, dayName, time: timeStr,
          driversNeeded, rosteredCount,
          shortfall: driversNeeded - rosteredCount,
          avgPax: Math.round(avgPax),
          sampleSize: historical.length,
        });
      }
    }
  }
  return gaps.sort((a, b) => a.date.localeCompare(b.date));
}

function SmartSchedulingPanel({ state }) {
  const gaps = React.useMemo(() =>
    computeSchedulingRecommendations(state.trips || [], state.driver_status || [], state.companies || []),
    [state.trips, state.driver_status, state.companies]
  );
  if (gaps.length === 0) return (
    <div style={{ fontSize: 10, color: COLORS.ghost }}>
      ✓ No staffing gaps detected in the next 7 days — or not enough historical data yet (need 3+ trips per time slot).
    </div>
  );
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      {gaps.map((gap, i) => (
        <div key={i} style={{ background: "rgba(245,166,35,0.06)", border: "1px solid rgba(245,166,35,0.25)", borderRadius: 4, padding: "8px 12px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 11, fontWeight: 700, color: COLORS.amber }}>
              {gap.dayName} {gap.date} @ {gap.time}
            </div>
            <div style={{ fontSize: 9, color: COLORS.ghost, marginTop: 2 }}>
              Avg {gap.avgPax} passengers ({gap.sampleSize} historical runs) · {gap.rosteredCount}/{gap.driversNeeded} drivers rostered
            </div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: COLORS.red, fontFamily: FONTS.head }}>
              -{gap.shortfall}
            </div>
            <div style={{ fontSize: 8, color: COLORS.ghost }}>driver{gap.shortfall !== 1 ? "s" : ""} short</div>
          </div>
        </div>
      ))}
    </div>
  );
}

// ── Weekly ops summary ────────────────────────────────────────────────────
// Computes a plain-language ops summary for the last 7 days.
// Designed to be: (a) shown in the dashboard, (b) copied and emailed,
// (c) callable from a Supabase Edge Function for automated Monday emails.
function computeWeeklySummary(trips, users, driverStatus) {
  const now = Date.now();
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;

  const lastWeek = trips.filter(t => {
    // Use raw epoch fields — booked_at and in_transit_at are display strings
    const d = t.booked_at_epoch || t.in_transit_at_epoch || 0;
    return Number(d) >= sevenDaysAgo;
  });

  const completed = lastWeek.filter(t => t.state === TRIP_STATE.ARCHIVED_COMPLETED);
  const cancelled = lastWeek.filter(t => t.state === TRIP_STATE.ARCHIVED_CANCELLED);
  const exceptions = lastWeek.filter(t => t.is_exception);
  const rejections = lastWeek.filter(t => t.rejection_reason);
  const noShows = lastWeek.filter(t => (t.no_shows || []).length > 0);
  const totalPax = completed.reduce((n, t) => n + (t.agent_ids?.length || 1), 0);
  const totalKm = completed.reduce((n, t) => n + (t.actual_distance_km || t.est_distance_km || 0), 0);

  // Per-driver stats for the week
  const driverStats = {};
  for (const t of completed) {
    if (!t.driver_id) continue;
    if (!driverStats[t.driver_id]) {
      const u = users.find(u => String(u.id) === String(t.driver_id));
      driverStats[t.driver_id] = { name: u?.name || t.driver_id, trips: 0, pax: 0, km: 0, rejections: 0 };
    }
    driverStats[t.driver_id].trips++;
    driverStats[t.driver_id].pax += (t.agent_ids?.length || 1);
    driverStats[t.driver_id].km += (t.actual_distance_km || t.est_distance_km || 0);
  }
  for (const t of rejections) {
    if (!t.rejection_driver_id) continue;
    if (!driverStats[t.rejection_driver_id]) {
      const u = users.find(u => String(u.id) === String(t.rejection_driver_id));
      driverStats[t.rejection_driver_id] = { name: u?.name || t.rejection_driver_id, trips: 0, pax: 0, km: 0, rejections: 0 };
    }
    driverStats[t.rejection_driver_id].rejections++;
  }

  const driverRows = Object.values(driverStats).sort((a, b) => b.trips - a.trips);
  const topDriver = driverRows[0] || null;
  const worstRejector = [...driverRows].sort((a, b) => b.rejections - a.rejections).find(d => d.rejections > 0);

  // Compliance flags
  const onlineDrivers = (driverStatus || []).filter(d => d.is_online).length;
  const expiredDocs = (driverStatus || []).filter(d => {
    const docs = d.documents || {};
    return DOC_TYPES.some(dt => docExpiryStatus(docs[dt.key]).status === "expired");
  }).length;

  return {
    period: "Last 7 days",
    completedTrips: completed.length,
    cancelledTrips: cancelled.length,
    totalPax,
    totalKm: Math.round(totalKm),
    exceptions: exceptions.length,
    rejections: rejections.length,
    noShows: noShows.length,
    topDriver,
    worstRejector,
    expiredDocs,
    onlineDrivers,
    driverRows,
  };
}

function formatWeeklySummaryText(s) {
  const lines = [
    `TransitOS — Weekly Ops Summary (${s.period})`,
    `========================================`,
    `Trips completed:   ${s.completedTrips}`,
    `Trips cancelled:   ${s.cancelledTrips}`,
    `Passengers moved:  ${s.totalPax}`,
    `Total km driven:   ${s.totalKm} km`,
    ``,
    `Exceptions:        ${s.exceptions}`,
    `Driver rejections: ${s.rejections}`,
    `No-shows:          ${s.noShows}`,
    ``,
    `Top driver:        ${s.topDriver ? s.topDriver.name + " — " + s.topDriver.trips + " trips, " + s.topDriver.pax + " pax" : "N/A"}`,
    s.worstRejector ? `⚠ Rejections:     ${s.worstRejector.name} (${s.worstRejector.rejections} rejection${s.worstRejector.rejections !== 1 ? "s" : ""} this week)` : "",
    s.expiredDocs > 0 ? `🚨 Expired docs:  ${s.expiredDocs} driver${s.expiredDocs !== 1 ? "s" : ""} with expired documents` : "",
    ``,
    `Generated by TransitOS on ${new Date().toLocaleDateString("en-ZA")}`,
  ].filter(l => l !== undefined);
  return lines.join("\n");
}

function WeeklyOpsSummaryPanel({ state }) {
  const [copied, setCopied] = React.useState(false);
  const s = React.useMemo(() =>
    computeWeeklySummary(state.trips || [], state.users || [], state.driver_status || []),
    [state.trips, state.users, state.driver_status]
  );
  const text = formatWeeklySummaryText(s);
  const copy = () => {
    navigator.clipboard.writeText(text).then(() => { setCopied(true); setTimeout(() => setCopied(false), 3000); });
  };

  return (
    <div style={{ background: COLORS.card, border: `1px solid ${COLORS.wire}`, borderRadius: 6, padding: 14, display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: COLORS.chalk, letterSpacing: 0.5 }}>📊 WEEKLY OPS SUMMARY</span>
        <div style={{ display: "flex", gap: 6 }}>
          <Button title={copied ? "✓ COPIED" : "📋 COPY FOR EMAIL"} variant="ghost" size="sm"
            style={{ borderColor: copied ? COLORS.green : COLORS.wire, color: copied ? COLORS.green : COLORS.ghost }}
            onClick={copy} />
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
        {[
          ["TRIPS DONE", s.completedTrips, COLORS.green],
          ["PASSENGERS", s.totalPax, COLORS.chalk],
          ["KM DRIVEN", s.totalKm, COLORS.chalk],
          ["EXCEPTIONS", s.exceptions, s.exceptions > 0 ? COLORS.amber : COLORS.ghost],
          ["REJECTIONS", s.rejections, s.rejections > 0 ? COLORS.red : COLORS.ghost],
          ["NO-SHOWS", s.noShows, s.noShows > 0 ? COLORS.amber : COLORS.ghost],
        ].map(([label, val, color]) => (
          <div key={label} style={{ background: COLORS.surface, border: `1px solid ${COLORS.wire}`, borderRadius: 4, padding: "5px 10px", minWidth: 80 }}>
            <div style={{ fontSize: 8, color: COLORS.ghost, letterSpacing: 0.8 }}>{label}</div>
            <div style={{ fontSize: 15, fontWeight: 800, color, fontFamily: FONTS.head }}>{val}</div>
          </div>
        ))}
      </div>
      {s.topDriver && (
        <div style={{ fontSize: 10, color: COLORS.ghost }}>
          🏆 Top driver: <span style={{ color: COLORS.green, fontWeight: 700 }}>{s.topDriver.name}</span> — {s.topDriver.trips} trips, {s.topDriver.pax} passengers, {Math.round(s.topDriver.km)} km
        </div>
      )}
      {s.worstRejector && (
        <div style={{ fontSize: 10, color: COLORS.amber }}>
          ⚠ Most rejections: {s.worstRejector.name} ({s.worstRejector.rejections} this week)
        </div>
      )}
      {s.expiredDocs > 0 && (
        <div style={{ fontSize: 10, color: COLORS.red, fontWeight: 700 }}>
          🚨 {s.expiredDocs} driver{s.expiredDocs !== 1 ? "s" : ""} with expired documents — check Drivers tab
        </div>
      )}
      <div style={{ fontSize: 9, color: COLORS.ghost }}>
        To automate Monday morning emails, deploy the TransitOS weekly-summary Edge Function (see docs).
      </div>
    </div>
  );
}

// ── Auto-grouping suggestions ─────────────────────────────────────────────
// Finds pairs/clusters of unassigned bookings that are good candidates
// to combine into one trip: same date, same direction, pickups within
// 8 km of each other, and no agent overlap.
function computeGroupSuggestions(unassigned) {
  const suggestions = [];
  const used = new Set();
  for (let i = 0; i < unassigned.length; i++) {
    if (used.has(i)) continue;
    const a = unassigned[i];
    const aCoord = a.pickup_sequence_coords?.[0];
    if (!aCoord?.lat) continue;
    const group = [a];
    const groupIdxs = [i];
    for (let j = i + 1; j < unassigned.length; j++) {
      if (used.has(j)) continue;
      const b = unassigned[j];
      if (b.scheduled_date !== a.scheduled_date) continue;
      if (b.direction !== a.direction) continue;
      const bCoord = b.pickup_sequence_coords?.[0];
      if (!bCoord?.lat) continue;
      const distKm = haversineKm(aCoord.lat, aCoord.lng, bCoord.lat, bCoord.lng);
      if (distKm > 8) continue;
      // No agent overlap
      const aAgents = new Set(a.agent_ids || []);
      const hasOverlap = (b.agent_ids || []).some(id => aAgents.has(id));
      if (hasOverlap) continue;
      group.push(b);
      groupIdxs.push(j);
      if (group.length >= 4) break; // cap at 4 per suggestion
    }
    if (group.length >= 2) {
      groupIdxs.forEach(idx => used.add(idx));
      const totalPax = group.reduce((n, t) => n + (t.agent_ids?.length || 1), 0);
      suggestions.push({ trips: group, totalPax, date: a.scheduled_date, direction: a.direction });
    }
  }
  return suggestions;
}

// ── Smart driver ranking ──────────────────────────────────────────────────
// Scores each available driver for a given trip on 4 dimensions:
//   proximity (0-40 pts) — closer to pickup = higher score
//   load      (0-30 pts) — fewer seats used today = higher score
//   history   (0-20 pts) — past acceptance rate (completions / assignments)
//   fit       (0-10 pts) — penalty if driver previously declined this agent
function scoreDriverForTrip(ds, u, distKm, state, tripAgentIds, trips) {
  let score = 0;
  const proxScore = distKm != null ? Math.max(0, 40 - (distKm / 30) * 40) : 0;
  score += proxScore;
  const cap = ds.capacity || DRIVER_CAPACITY;
  const load = trips.filter(t =>
    String(t.driver_id) === String(ds.driver_id) &&
    [TRIP_STATE.ASSIGNED, TRIP_STATE.DRIVER_CONFIRMED, TRIP_STATE.IN_TRANSIT].includes(t.state)
  ).reduce((n, t) => n + Math.max(1, t.agent_ids?.length || 0), 0);
  score += Math.max(0, 30 - (load / cap) * 30);
  const driverTrips = trips.filter(t => t.driver_id === ds.driver_id || (t.declinedBy || []).some(id => String(id) === String(ds.driver_id)));
  const completed = driverTrips.filter(t => String(t.driver_id) === String(ds.driver_id) && t.state === TRIP_STATE.ARCHIVED_COMPLETED).length;
  const declined = driverTrips.filter(t => (t.declinedBy || []).some(id => String(id) === String(ds.driver_id))).length;
  const total = completed + declined;
  const acceptRate = total > 0 ? completed / total : 1;
  score += acceptRate * 20;
  const agentSet = new Set(tripAgentIds || []);
  const prevDeclinedThisAgent = trips.some(t =>
    (t.declinedBy || []).some(id => String(id) === String(ds.driver_id)) &&
    (t.agent_ids || []).some(aid => agentSet.has(aid))
  );
  if (prevDeclinedThisAgent) score -= 10;
  return { score: Math.round(Math.max(0, Math.min(100, score))), proxScore: Math.round(proxScore), load, acceptRate, prevDeclinedThisAgent };
}

const _routeCache = new Map(); // key → { km, ts }
const ROUTE_CACHE_TTL_MS = 30 * 60 * 1000; // 30 min

// ── High-risk-zone routing avoidance ────────────────────────────────────
// Module-level cache of TomTom avoidAreas rectangles, refreshed whenever
// state.high_risk_zones changes (see fetchHighRiskZones) — read directly
// by tomtomRealRouteKm/tomtomBestOrderOnce rather than threaded as an
// explicit parameter through every call site (buildPickupSequenceTomTom,
// useSortedDropoffs, tomtomOptimalStopOrder, etc.), matching the
// _routeCache/_tomtomSortCache module-level-cache pattern already used in
// this file. Keeps the change contained to the two functions that actually
// hit the network, instead of touching every already-fixed call chain.
let _highRiskAvoidRectangles = null;
// TomTom's avoidAreas.rectangles accepts a maximum of 10 elements — active
// zones beyond that are silently dropped (with a console warning) rather
// than causing the whole request to fail.
function setHighRiskAvoidZones(zones) {
  const active = (zones || []).filter(z => z.active && z.lat != null && z.lng != null && z.radius_km > 0);
  if (!active.length) { _highRiskAvoidRectangles = null; return; }
  if (active.length > 10) console.warn(`[HighRiskZones] ${active.length} active zones, only the first 10 will be avoided (TomTom's avoidAreas limit).`);
  _highRiskAvoidRectangles = active.slice(0, 10).map(z => {
    // Simple lat/lng degree approximation (111km/degree latitude,
    // adjusted for longitude by cos(latitude)) — plenty precise for a
    // safety-margin bounding box around a radius-based zone; TomTom only
    // accepts axis-aligned rectangles, not circles, so this is the
    // necessary conversion, not a shortcut.
    const latDelta = z.radius_km / 111;
    const lngDelta = z.radius_km / (111 * Math.cos(z.lat * Math.PI / 180));
    return {
      southWestCorner: { latitude: z.lat - latDelta, longitude: z.lng - lngDelta },
      northEastCorner: { latitude: z.lat + latDelta, longitude: z.lng + lngDelta },
    };
  });
}

function routeCacheKey(coords, departAtEpoch) {
  const waypts = coords.map(c => `${c.lat.toFixed(4)},${c.lng.toFixed(4)}`).join("|");
  // Round to the nearest hour so trips booked at 14:26 and 14:58 for a
  // 21:00 run don't generate two separate cache entries.
  const hourBucket = departAtEpoch ? Math.floor(Number(departAtEpoch) / 3600000) : 0;
  return `${waypts}::${hourBucket}`;
}

function routeCacheGet(key) {
  const entry = _routeCache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.ts > ROUTE_CACHE_TTL_MS) { _routeCache.delete(key); return null; }
  return entry.km;
}

function routeCacheSet(key, km) {
  _routeCache.set(key, { km, ts: Date.now() });
}

// ── FEATURE: Road-type avoidance ───────────────────────────────────────────
// avoidUnpavedRoads: never route via informal-settlement unmaintained tracks
// avoidTollRoads: no toll roads in Cape Town but good practice for future
// (N1 east, N2 toll plazas if Pearce & Sons ever expands to Paarl/Stellenbosch)
// Note: TomTom uses comma-separated values in the `avoid` param:
//   avoid=tollRoads,unpavedRoads,ferries
// Using unpavedRoads only for now — add tollRoads if needed.
const TOMTOM_AVOID_PARAM = "&avoid=unpavedRoads";

async function tomtomAutocompleteSearch(query) {
  if (!TOMTOM_API_KEY || !query || query.trim().length < 2) return [];
  try {
    const url = `https://api.tomtom.com/search/2/search/${encodeURIComponent(query)}.json` +
      `?key=${TOMTOM_API_KEY}&countrySet=ZA&limit=6` +
      `&topLeft=${CPT_BOUNDS.north},${CPT_BOUNDS.west}&btmRight=${CPT_BOUNDS.south},${CPT_BOUNDS.east}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`TomTom search returned ${res.status}`);
    const data = await res.json();
    return (data.results || []).map(r => ({
      label: r.address?.freeformAddress || r.poi?.name || query,
      area: r.address?.municipalitySubdivision || r.address?.municipality || "Cape Town",
      lat: r.position?.lat, lng: r.position?.lon,
      source: "tomtom",
    })).filter(r => r.lat != null && r.lng != null);
  } catch (e) {
    console.warn("[TomTom] autocomplete failed, falling back to Nominatim:", e.message);
    return [];
  }
}

// TomTom's Geocoding endpoint is the right tool for a complete, typed-out
// address (as opposed to the Search/autocomplete endpoint above, built for
// real-time partial typing) — used by the manual "Type Address" entry
// path to resolve real coordinates for the app's internal route/distance
// math, the same role Google's Geocoding API played before this rebuild.
async function tomtomGeocodeAddress(address) {
  if (!TOMTOM_API_KEY || !address?.trim()) return null;
  try {
    const url = `https://api.tomtom.com/search/2/geocode/${encodeURIComponent(address)}.json` +
      `?key=${TOMTOM_API_KEY}&countrySet=ZA&limit=1`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`TomTom geocode returned ${res.status}`);
    const data = await res.json();
    const r = data.results?.[0];
    if (!r) return null;
    return {
      label: r.address?.freeformAddress || address,
      area: r.address?.municipalitySubdivision || r.address?.municipality || "Cape Town",
      lat: r.position?.lat, lng: r.position?.lon,
      source: "tomtom-geocoding",
    };
  } catch (e) {
    console.warn("[TomTom] geocoding failed:", e.message);
    return null;
  }
}

// Reverse-geocode a GPS coordinate to a human-readable address using TomTom.
// Used to record the actual street address where each agent was picked up/dropped off.
// Returns a label string or null if TomTom is unavailable/fails.
async function tomtomReverseGeocode(lat, lng) {
  if (!TOMTOM_API_KEY || lat == null || lng == null) return null;
  try {
    const url = `https://api.tomtom.com/search/2/reverseGeocode/${lat},${lng}.json` +
      `?key=${TOMTOM_API_KEY}&returnSpeedLimit=false&returnRoadUse=false`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const addr = data.addresses?.[0]?.address;
    if (!addr) return null;
    return addr.freeformAddress || `${addr.streetName || ""} ${addr.streetNumber || ""}, ${addr.municipality || ""}`.trim();
  } catch (e) {
    console.warn("[TomTom] reverse geocode failed:", e.message);
    return null;
  }
}

// Use TomTom Routing API to sort an array of dropoff coords into the optimal
// road-distance order starting from an anchor (company location for OUTBOUND).
// Returns the re-ordered coords array, or null if TomTom is unavailable/fails.
// Falls back to haversine nearest-neighbour in the caller when this returns null.
//
// TomTom /calculateRoute with computeBestOrder=true reorders INTERMEDIATE waypoints
// (it always fixes the first and last locations as start/end). To allow ALL dropoff
// stops to be freely reordered, we append the anchor again as the final destination,
// making it a "leave company → visit all homes in best order → return to company"
// route. This is only used to determine ordering — not as actual navigation.
//
// With 3 dropoffs and anchor repeated: anchor:d1:d2:d3:anchor
//   TomTom fixes: anchor (start) and anchor (end) — all of d1,d2,d3 are free.
//   optimizedWaypoints returns d1,d2,d3 in optimal road order.
// Use TomTom Routing API to get the actual driving distance (km) for a
// sequence of coordinates: startAnchor → each ordered pickup → each ordered dropoff.
// Returns null if TomTom is unavailable or the call fails; caller falls back
// to haversine estimate in that case.
async function tomtomRealRouteKm(startAnchor, orderedPickups, orderedDropoffs, departAtEpoch = null) {
  if (!TOMTOM_API_KEY || !startAnchor) return null;
  try {
    // Build the full waypoint list — starting from the FIRST PICKUP, not
    // startAnchor. "Driver's full route" means first pickup through last
    // drop-off, per explicit requirement, so the company-to-first-pickup
    // leg (or wherever the driver actually was at start-trip time) is
    // deliberately excluded from this distance — startAnchor is only
    // used elsewhere (buildPickupSequence/buildDropoffSequence) to
    // determine WHICH pickup is nearest for sequencing, not counted here.
    const coords = [];
    for (const p of orderedPickups) {
      if (p.coord?.lat != null) coords.push(p.coord);
    }
    for (const t of orderedDropoffs) {
      for (const c of (t.dropoff_sequence_coords || [t.dropoff_sequence_coords?.[0]]).filter(Boolean)) {
        if (c?.lat != null) coords.push(c);
      }
    }
    // Safety net: collapse any consecutive or repeated waypoints that sit
    // at the same physical location before requesting a route. A route
    // that revisits an identical point (e.g. from a stale duplicate
    // dropoff entry left over from an earlier bug, or simply two
    // passengers who happen to share one exact address) gets an
    // artificial out-and-back leg added to it by the routing engine,
    // inflating the total — confirmed in production: a 3-passenger trip
    // was showing 110km for a route that Google Maps confirms is 76km
    // for the same stop sequence. Keeps the FIRST occurrence's position
    // in the sequence so ordering is unaffected; only true duplicates
    // (same coordinate to ~1m precision) are removed, never two agents
    // who are merely nearby but at genuinely different addresses.
    const dedupedCoords = dedupeCoordsByLocation(coords);
    if (dedupedCoords.length < 2) return null;
    const locations = dedupedCoords.map(c => `${c.lat},${c.lng}`).join(":"); // TomTom calculateRoute: latitude,longitude
    // departAt: use the trip's scheduled time so TomTom applies historical
    // traffic patterns for that hour, not live conditions at booking time.
    const departAtParam = departAtEpoch
      ? `&departAt=${new Date(departAtEpoch).toISOString().slice(0, 19)}`
      : "";
    // Feature 1: route cache — skip the API call if we've asked the same
    // question in the last 30 minutes (same waypoints + same hour window).
    const cacheKey = routeCacheKey(dedupedCoords, departAtEpoch);
    const cached = routeCacheGet(cacheKey);
    if (cached != null) { console.log("[TomTom] route cache hit"); return cached; }
    // Feature 3: avoid unpaved roads.
    // NOTE: this request previously also appended a "supportingPoints"
    // query-string param (a preferred-arterial-corridor nudge for Cape
    // Flats routes). Removed 2026-08-01 — confirmed live against TomTom's
    // API that supportingPoints is rejected outright as a query-string
    // parameter ("Invalid request: parameter [supportingPoints] not
    // supported", HTTP 400) regardless of whether avoidAreas is also
    // present, so it had NEVER actually worked: every Cape Flats route
    // silently 400'd and fell back to a less-accurate haversine estimate.
    // Worse, since most real high-risk-zone candidates ARE in the Cape
    // Flats, the same 400 also poisoned the entire request whenever a
    // zone was active, meaning avoidAreas (the actual safety feature)
    // never even reached TomTom for evaluation on exactly the routes it
    // matters most for. Removing this broken param fixes both: real
    // routes now get TomTom's actual computed distance instead of the
    // haversine fallback, AND avoidAreas can now actually take effect.
    // Re-adding a working corridor nudge later requires moving
    // supportingPoints into the POST body (confirmed that shape IS
    // accepted) AND re-deriving real drivable waypoints first — a live
    // test of the old hardcoded CAPE_FLATS_CORRIDOR points showed TomTom
    // routing part of that path through a non-car travel segment, nearly
    // doubling the distance — so don't just move the same points into the
    // body without re-validating them.
    const url = `https://api.tomtom.com/routing/1/calculateRoute/${locations}/json` +
      `?key=${TOMTOM_API_KEY}&routeType=fastest&traffic=true&travelMode=car${departAtParam}${TOMTOM_AVOID_PARAM}`;
    // High-risk-zone avoidance requires a POST body — avoidAreas is not a
    // GET query parameter (confirmed against TomTom's docs) — with every
    // other parameter still on the query string as normal, since a
    // parameter can't be supplied in both the query string and POST body
    // at once.
    const res = _highRiskAvoidRectangles
      ? await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ avoidAreas: { rectangles: _highRiskAvoidRectangles } }),
        })
      : await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const metres = data.routes?.[0]?.summary?.lengthInMeters;
    if (metres == null) return null;
    const km = metres / 1000;
    routeCacheSet(cacheKey, km);
    return km; // → km
  } catch (e) {
    console.warn("[TomTom] real route km failed:", e.message);
    return null;
  }
}

// ── In-app driver navigation (Feature: replaces the external Waze handoff) ──
// Fetches a real drivable route + turn-by-turn text instructions for the
// embedded nav map (DriverNavMap) — a single from→to leg, unlike
// tomtomRealRouteKm above (which stitches a driver's WHOLE multi-stop day
// together for distance/compliance purposes, not for live turn-by-turn).
// Respects the same high-risk-zone avoidance as every other routing call in
// this file — a driver actively navigating should never be routed through a
// flagged area any more than the background distance calculations should.
// Returns null on any failure; caller falls back to a straight line /
// haversine estimate rather than breaking navigation entirely.
async function tomtomNavRoute(fromCoord, toCoord) {
  if (!TOMTOM_API_KEY || !fromCoord?.lat || !toCoord?.lat) return null;
  try {
    const locations = `${fromCoord.lat},${fromCoord.lng}:${toCoord.lat},${toCoord.lng}`; // lat,lng — see the standing warning elsewhere in this file
    const url = `https://api.tomtom.com/routing/1/calculateRoute/${locations}/json` +
      `?key=${TOMTOM_API_KEY}&routeType=fastest&traffic=true&travelMode=car` +
      `&instructionsType=text&language=en-GB${TOMTOM_AVOID_PARAM}`;
    const res = _highRiskAvoidRectangles
      ? await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ avoidAreas: { rectangles: _highRiskAvoidRectangles } }),
        })
      : await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const route = data.routes?.[0];
    if (!route) return null;
    const points = (route.legs || []).flatMap(leg => (leg.points || []).map(p => ({ lat: p.latitude, lng: p.longitude })));
    if (points.length < 2) return null;
    const instructions = (route.guidance?.instructions || []).map(ins => ({
      offsetM: ins.routeOffsetInMeters ?? 0,
      lat: ins.point?.latitude, lng: ins.point?.longitude,
      maneuver: ins.maneuver || null, message: ins.message || ins.combinedMessage || "Continue",
      street: ins.street || null,
    })).filter(ins => ins.lat != null);
    const metres = route.summary?.lengthInMeters;
    const seconds = route.summary?.travelTimeInSeconds;
    return {
      points, instructions,
      distanceKm: metres != null ? metres / 1000 : null,
      etaMin: seconds != null ? Math.max(1, Math.round(seconds / 60)) : null,
    };
  } catch (e) {
    console.warn("[TomTom] nav route failed:", e.message);
    return null;
  }
}

// Runs one computeBestOrder request for a fixed set of free (reorderable)
// stops plus one pinned end waypoint. Returns { order, km } — order is
// freeStops reordered by TomTom + pinnedEnd appended, km is the ACTUAL total
// route distance TomTom computed for that specific order (not an estimate) —
// or null if the request failed or the response shape didn't match.
async function tomtomBestOrderOnce(anchorCoord, freeStops, pinnedEnd, departAtEpoch) {
  const allWaypoints = [anchorCoord, ...freeStops, pinnedEnd];
  const locations = allWaypoints.map(c => `${c.lat},${c.lng}`).join(":"); // TomTom calculateRoute: latitude,longitude
  const departAtParam = departAtEpoch
    ? `&departAt=${new Date(departAtEpoch).toISOString().slice(0, 19)}`
    : "";
  // This request never included a supportingPoints param to begin with —
  // confirmed against the live API that TomTom rejects it outright as a
  // query-string parameter regardless of computeBestOrder, so there was
  // never anything to strip here. (tomtomRealRouteKm above USED to send
  // one — see its comment for why that was removed entirely.)
  const url = `https://api.tomtom.com/routing/1/calculateRoute/${locations}/json` +
    `?key=${TOMTOM_API_KEY}&computeBestOrder=true&routeType=fastest&traffic=true&travelMode=car${departAtParam}${TOMTOM_AVOID_PARAM}`;
  // High-risk-zone avoidance requires a POST body — see the identical
  // note/reasoning in tomtomRealRouteKm above.
  const res = _highRiskAvoidRectangles
    ? await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ avoidAreas: { rectangles: _highRiskAvoidRectangles } }),
      })
    : await fetch(url);
  if (!res.ok) {
    let errBody = "";
    try { errBody = JSON.stringify(await res.json(), null, 2); } catch { errBody = await res.text().catch(() => ""); }
    console.error(`[TomTom] Routing API error ${res.status} — URL: ${url.replace(TOMTOM_API_KEY, "***")}`);
    console.error(`[TomTom] Error body: ${errBody}`);
    throw new Error(`TomTom routing returned ${res.status}: ${errBody.slice(0, 200)}`);
  }
  const data = await res.json();
  // IMPORTANT — confirmed in production against real API responses:
  // optimizedWaypoints does NOT include either fixed anchor (start or end).
  // providedIndex is 0-indexed relative ONLY to the "soft" reorderable
  // waypoints we listed (`freeStops`), not the full allWaypoints array. A
  // request with 2 free stops → optimizedWaypoints has exactly 2 entries,
  // with providedIndex values 0 and 1.
  const optimized = data.routes?.[0]?.optimizedWaypoints;
  const totalMetres = data.routes?.[0]?.summary?.lengthInMeters;
  if (!optimized || optimized.length !== freeStops.length || totalMetres == null) {
    console.warn(`[TomTom] optimizedWaypoints count mismatch: got ${optimized?.length ?? 0}, expected exactly ${freeStops.length}. Falling back to haversine.`);
    return null;
  }
  // CRITICAL: optimizedWaypoints from the API is consistently ordered by
  // providedIndex (0,1,2,...) — it is NOT already in visiting order. The
  // actual optimal sequence is given by each entry's optimizedIndex field.
  // Sorting by optimizedIndex BEFORE mapping to coordinates is what
  // actually applies TomTom's computed reordering — without this sort,
  // .map(w => freeStops[w.providedIndex]) just reconstructs the original
  // input order (since the array itself is providedIndex-ordered),
  // silently discarding every genuine reorder TomTom returns. Confirmed in
  // production: a request with providedIndex/optimizedIndex pairs (0,0)
  // (1,2) (2,1) — a real, valid reordering (visit index 0, then 2, then 1)
  // — was being flattened straight back to [0,1,2] by this bug, always
  // matching the un-optimized input order.
  const reorderedFree = [...optimized]
    .sort((a, b) => a.optimizedIndex - b.optimizedIndex)
    .filter(w => w.providedIndex >= 0 && w.providedIndex < freeStops.length)
    .map(w => freeStops[w.providedIndex])
    .filter(Boolean);
  if (reorderedFree.length !== freeStops.length) return null;
  return { order: [...reorderedFree, pinnedEnd], km: totalMetres / 1000 };
}

// Validates a single coordinate is non-null, non-zero, and within
// a plausible geographic range. Coordinates that geocoded to [0,0]
// (geocoder error) or are outside the bounding box of greater Cape Town
// will cause TomTom to return 400 or route to the wrong place entirely.
// Bounding box covers Cape Town metro area with generous margins.
const CT_BOUNDS = { minLat: -35.0, maxLat: -33.0, minLng: 17.5, maxLng: 19.5 };
function isValidCoord(c) {
  if (c == null || c.lat == null || c.lng == null) return false;
  if (c.lat === 0 && c.lng === 0) return false; // geocoder fallback sentinel
  if (Number.isNaN(c.lat) || Number.isNaN(c.lng)) return false;
  if (c.lat < CT_BOUNDS.minLat || c.lat > CT_BOUNDS.maxLat) return false;
  if (c.lng < CT_BOUNDS.minLng || c.lng > CT_BOUNDS.maxLng) return false;
  return true;
}

async function tomtomOptimalStopOrder(anchorCoord, stopCoords, departAtEpoch = null, destinationCoord = null) {
  if (!TOMTOM_API_KEY || !anchorCoord || stopCoords.length <= 1) return null;
  if (!isValidCoord(anchorCoord)) {
    console.warn("[TomTom] anchorCoord is invalid or outside Cape Town bounds:", anchorCoord);
    return null;
  }
  if (destinationCoord != null && !isValidCoord(destinationCoord)) {
    console.warn("[TomTom] destinationCoord is invalid:", destinationCoord);
    destinationCoord = null;
  }
  const valid = stopCoords.filter(c => {
    if (isValidCoord(c)) return true;
    console.warn("[TomTom] Dropping stop with invalid/missing coordinates:", c?.label ?? c);
    return false;
  });
  if (valid.length <= 1) {
    console.warn("[TomTom] Not enough valid stop coordinates after filtering (need ≥2).");
    return null;
  }
  try {
    // CRITICAL — confirmed against real production data: computeBestOrder
    // with BOTH a fixed start AND a fixed end anchor solves a CLOSED-LOOP
    // ("leave anchor, visit all stops, return to anchor") problem, not the
    // one-way trip we actually want. For any given cyclic order of stops,
    // a round trip's total distance is the same regardless of which
    // direction you traverse it or where you "start" within the loop —
    // so TomTom had no real basis to prefer one order over another and
    // was simply echoing back whatever order we provided as already
    // "optimal" for the round-trip objective, even when the true ONE-WAY
    // distance (no return leg) differed by 30+ km between orderings.
    // Verified with real Google Maps data across multiple stop
    // combinations: TomTom consistently returned optimizedIndex ===
    // providedIndex ("no change needed") regardless of input order —
    // exactly the symptom of solving the wrong (cyclic) problem.
    //
    // Fix: fix ONLY the start point. Every dropoff is a free waypoint,
    // with NO forced return to the anchor — this is what "find the
    // shortest one-way route visiting these stops" genuinely means.
    // Adding a fixed destination does NOT create a closed loop (as a fixed
    // start+end would if start===end) — it means "shortest path from
    // start, visiting all intermediate stops in the best order, ending at
    // destination."
    //
    // CONFIRMED against the live API: computeBestOrder always treats the
    // LAST waypoint in the request as a second fixed anchor too — not just
    // the first. When we have a genuine destination (INBOUND, ending at
    // the company office), that's exactly what we want: pin it as the end,
    // every dropoff in between is free.
    //
    // When there's no genuine destination (OUTBOUND), there's nothing
    // correct to pin as "last" — WHICH stop should be visited last is
    // itself part of what "shortest route" means, and TomTom's API will
    // never revisit that choice once one stop is pinned as the fixed end.
    // An earlier version of this fix pinned whichever stop the haversine
    // pre-sort happened to place last — but that's a straight-line guess,
    // not a road-distance one, and it can easily disagree with the true
    // shortest order (rivers, highways, one-way streets all change which
    // stop is actually cheapest to visit last). The only way to actually
    // find the true shortest one-way route is to try EACH stop as the
    // candidate last stop, let TomTom optimize the rest for each, and keep
    // whichever candidate's real total road distance comes out shortest.
    // Stop counts here are always small (1-4 typical dropoffs per trip),
    // so this is at most a handful of extra API calls, run concurrently.
    const hasRealDestination = destinationCoord?.lat != null;
    if (hasRealDestination) {
      const result = await tomtomBestOrderOnce(anchorCoord, valid, destinationCoord, departAtEpoch);
      if (!result) return null;
      // The destination itself is never a real dropoff — exclude it from
      // the returned order (it was only needed to anchor the computation).
      const reordered = result.order.slice(0, -1);
      // Must be the exact complement of `valid` (isValidCoord), not just a
      // null-check — a stop rejected for being {0,0}, NaN, or outside
      // CT_BOUNDS would otherwise land in neither bucket and vanish, making
      // the returned order one stop short. The caller (useSortedDropoffs)
      // treats any length mismatch as "TomTom failed" and discards the
      // result — so this silently misreported a real, correct TomTom
      // response as a failure whenever a bad (not merely missing) coordinate
      // was in the mix.
      const invalid = stopCoords.filter(c => !isValidCoord(c));
      return [...reordered, ...invalid];
    }
    const candidates = await Promise.all(valid.map(async (candidateEnd, i) => {
      const freeStops = valid.filter((_, j) => j !== i);
      try { return await tomtomBestOrderOnce(anchorCoord, freeStops, candidateEnd, departAtEpoch); }
      catch (e) { console.warn(`[TomTom] candidate end #${i} failed:`, e.message); return null; }
    }));
    let best = null;
    for (const c of candidates) {
      if (c && (!best || c.km < best.km)) best = c;
    }
    if (!best) return null;
    // Must be the exact complement of `valid` (isValidCoord) — see the
    // matching comment on the hasRealDestination branch above. This is the
    // OUTBOUND (no-destination) branch, the more commonly hit of the two,
    // and the prior fix here didn't actually land: this line has 4-space
    // indent vs. 6 for the other branch, so a replace_all on the identical
    // old line only matched the other occurrence.
    const invalid = stopCoords.filter(c => !isValidCoord(c));
    return [...best.order, ...invalid];
  } catch (e) {
    console.warn("[TomTom] route optimization failed, falling back to haversine:", e.message);
    return null;
  }
}

async function nominatimSearch(query) {
  if (!query || query.trim().length < 2) return [];
  try {
    const params = new URLSearchParams({
      q: query,
      format: "jsonv2",
      addressdetails: "1",
      limit: "6",
      countrycodes: "za",
      viewbox: `${CPT_BOUNDS.west},${CPT_BOUNDS.north},${CPT_BOUNDS.east},${CPT_BOUNDS.south}`,
      bounded: "1",
      // Nominatim's usage policy asks for a way to identify the calling
      // app. Browsers block JS from setting a custom User-Agent header for
      // security reasons, so their documented workaround is to identify
      // via this query param instead. Swap in a real contact address if
      // you have one — it's optional but keeps you in good standing under
      // their usage policy at higher request volumes.
      // email: "your-real-contact@yourdomain.com",
    });
    const res = await fetch(`https://nominatim.openstreetmap.org/search?${params}`, {
      headers: { "Accept-Language": "en" },
    });
    if (!res.ok) {
      console.warn("[Nominatim] HTTP error:", res.status);
      return [];
    }
    const data = await res.json();
    if (!Array.isArray(data) || data.length === 0) return [];
    return data.map(r => {
      const addr = r.address || {};
      const houseNum = addr.house_number || "";
      const road = addr.road || addr.pedestrian || addr.footway || "";
      const suburb = addr.suburb || addr.neighbourhood || addr.city_district || addr.town || "";
      const streetLine = road ? `${houseNum ? houseNum + " " : ""}${road}` : "";
      const label = streetLine
        ? `${streetLine}${suburb ? `, ${suburb}` : ""}, Cape Town`
        : (r.display_name || query);
      return {
        label,
        area: suburb || "Cape Town",
        lat: parseFloat(r.lat),
        lng: parseFloat(r.lon),
        source: "osm",
      };
    }).filter(r => !isNaN(r.lat) && !isNaN(r.lng));
  } catch (e) {
    console.warn("[Nominatim] search failed, falling back to offline DB:", e.message);
    return [];
  }
}

async function unifiedAddressSearch(query) {
  const offline = staticSearch(query);
  if (TOMTOM_API_KEY) {
    const tomtom = await tomtomAutocompleteSearch(query);
    if (tomtom.length > 0) return { results: tomtom, liveOk: true, source: "tomtom" };
  }
  const live = await nominatimSearch(query);
  if (live.length > 0) return { results: live, liveOk: true, source: "nominatim" };
  return { results: offline, liveOk: false, source: "offline" };
}

/* ---------- SUPABASE CLIENT (web) ----------
   Note: this file assumes @supabase/supabase-js is available as an ES
   import in your build (Vite/CRA/Next). If you're pasting this into a
   sandboxed preview tool without npm access, comment out the import below
   and the app will fall back to the in-memory reducer automatically. */
import { createClient } from "@supabase/supabase-js";

const SUPABASE_URL = "https://kwkgiylwnafwimxqmjwk.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_Kyne7Q6PJ2uKmcfslI-qNQ_CX-m7mxF";

const supabase = (SUPABASE_URL && SUPABASE_ANON_KEY)
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: false },
      realtime: { params: { eventsPerSecond: 10 } },
    })
  : null;

// Instant street-name suggestions from the bulk-loaded City of Cape Town
// street name reference table (18k+ names, no house numbers/coordinates).
// This is meant to be near-instant feedback while typing — picking a
// suggestion re-runs the live Nominatim search scoped to that exact name,
// which is what actually resolves a coordinate.
async function streetNameSearch(query) {
  if (!supabase || !query || query.trim().length < 2) return [];
  const q = query.trim().toUpperCase();
  try {
    const { data, error } = await supabase
      .from("cape_town_street_names")
      .select("street_name")
      .like("street_name_upper", `${q}%`)
      .order("street_name")
      .limit(8);
    if (error) {
      console.warn("[StreetNames] query failed:", error.message);
      return [];
    }
    return (data || []).map(r => r.street_name);
  } catch (e) {
    console.warn("[StreetNames] query failed:", e.message);
    return [];
  }
}

